/**
 * ОТВЕТСТВЕННОСТЬ: Управление персистентным состоянием (localStorage).
 * ДОЛЖЕН СОДЕРЖАТЬ: Все вызовы useLocalStorage для инструментов, деталей, настроек и т.д.
 * НЕ ДОЛЖЕН СОДЕРЖАТЬ: Логику обработки (бизнес-логику) или JSX.
 */
import { useLocalStorage } from './useLocalStorage';
import { Tool, Part, ParametricScript, NestLayout, TurretLayout, MachineSettings, OptimizerSettings, TeachCycle } from '../types';
import { initialTools, initialParts, initialNests, initialTurretLayouts, initialScripts, defaultMachineSettings, defaultOptimizerSettings } from '../data/initialData';

export const useAppPersistence = () => {
    const [tools, setTools] = useLocalStorage<Tool[]>('fp_tools', initialTools);
    const [parts, setParts] = useLocalStorage<Part[]>('fp_parts', initialParts);
    const [scripts, setScripts] = useLocalStorage<ParametricScript[]>('fp_scripts', initialScripts);
    const [nests, setNests] = useLocalStorage<NestLayout[]>('fp_nests', initialNests);
    const [turretLayouts, setTurretLayouts] = useLocalStorage<TurretLayout[]>('fp_turret_layouts', initialTurretLayouts);
    const [machineSettings, setMachineSettings] = useLocalStorage<MachineSettings>('fp_machine_settings', defaultMachineSettings);
    const [optimizerSettings, setOptimizerSettings] = useLocalStorage<OptimizerSettings>('fp_optimizer_settings', defaultOptimizerSettings);
    const [teachCycles, setTeachCycles] = useLocalStorage<TeachCycle[]>('fp_teach_cycles', []);

    return {
        tools, setTools,
        parts, setParts,
        scripts, setScripts,
        nests, setNests,
        turretLayouts, setTurretLayouts,
        machineSettings, setMachineSettings,
        optimizerSettings, setOptimizerSettings,
        teachCycles, setTeachCycles
    };
};

/**
 * ОТВЕТСТВЕННОСТЬ: Состояние редактирования детали, выбор инструментов, Snap-режимы и обучение.
 * ДОЛЖЕН СОДЕРЖАТЬ: activePart, selectedToolId, snapMode, teachMode и интеграцию useManualPunch.
 * НЕ ДОЛЖЕН СОДЕРЖАТЬ: Логику раскроя или персистентность.
 */
import { useState, useMemo } from 'react';
import { Part, Tool, ManualPunchMode, SnapMode, NibbleSettings, DestructSettings } from '../types';
import { getGeometryFromEntities } from '../services/geometry';
import { useManualPunch } from './useManualPunch';

interface UseEditorStateProps {
    tools: Tool[];
    onAddPunches: (punches: any[]) => void;
}

export const useEditorState = ({ tools, onAddPunches }: UseEditorStateProps) => {
    const [activePart, setActivePart] = useState<Part | null>(null);
    const [selectedToolId, setSelectedToolId] = useState<string | null>(null);
    const [selectedPunchId, setSelectedPunchId] = useState<string | null>(null);
    const [manualPunchMode, setManualPunchMode] = useState<ManualPunchMode>(ManualPunchMode.Punch);
    const [punchOrientation, setPunchOrientation] = useState(0);
    const [snapMode, setSnapMode] = useState<SnapMode>(SnapMode.Vertex);
    const [punchOffset, setPunchOffset] = useState<number>(0);
    const [nibbleSettings, setNibbleSettings] = useState<NibbleSettings>({ 
        extensionStart: 0, extensionEnd: 0, minOverlap: 1, hitPointMode: 'offset', toolPosition: 'long' 
    });
    const [destructSettings, setDestructSettings] = useState<DestructSettings>({ 
        overlap: 0.7, scallop: 0.25, notchExpansion: 0.25 
    });

    const [teachMode, setTeachMode] = useState(false);
    const [selectedSegmentIds, setSelectedSegmentIds] = useState<number[]>([]);
    const [selectedTeachPunchIds, setSelectedTeachPunchIds] = useState<string[]>([]);

    const activePartProcessedGeometry = useMemo(() => 
        activePart ? getGeometryFromEntities(activePart) : null, [activePart]
    );

    const selectedTool = tools.find(t => t.id === selectedToolId) || null;

    const manualPunch = useManualPunch({
        activePart,
        activePartProcessedGeometry,
        selectedTool,
        manualPunchMode,
        punchOrientation,
        punchOffset,
        snapMode,
        nibbleSettings,
        destructSettings,
        onAddPunches,
        setSelectedPunchId
    });

    return {
        activePart, setActivePart,
        selectedToolId, setSelectedToolId,
        selectedPunchId, setSelectedPunchId,
        manualPunchMode, setManualPunchMode,
        punchOrientation, setPunchOrientation,
        snapMode, setSnapMode,
        punchOffset, setPunchOffset,
        nibbleSettings, setNibbleSettings,
        destructSettings, setDestructSettings,
        teachMode, setTeachMode,
        selectedSegmentIds, setSelectedSegmentIds,
        selectedTeachPunchIds, setSelectedTeachPunchIds,
        activePartProcessedGeometry,
        selectedTool,
        manualPunch
    };
};

/**
 * ОТВЕТСТВЕННОСТЬ: Процесс раскроя, прогресс, выбор листа и ID активного раскроя.
 * ДОЛЖЕН СОДЕРЖАТЬ: activeNestId, activeSheetIndex, progress, status, selectedNestPartId.
 * НЕ ДОЛЖЕН СОДЕРЖАТЬ: Логику редактора или симуляции.
 */
import { useState } from 'react';
import { NestLayout } from '../types';

export const useNestingState = (initialNestId: string | null) => {
    const [activeNestId, setActiveNestId] = useState<string | null>(initialNestId);
    const [activeSheetIndex, setActiveSheetIndex] = useState<number>(0);
    const [selectedNestPartId, setSelectedNestPartId] = useState<string | null>(null);
    const [isNestingProcessing, setIsNestingProcessing] = useState(false);
    const [nestingProgress, setNestingProgress] = useState(0);
    const [nestingStatus, setNestingStatus] = useState('');

    return {
        activeNestId, setActiveNestId,
        activeSheetIndex, setActiveSheetIndex,
        selectedNestPartId, setSelectedNestPartId,
        isNestingProcessing, setIsNestingProcessing,
        nestingProgress, setNestingProgress,
        nestingStatus, setNestingStatus
    };
};

/**
 * ОТВЕТСТВЕННОСТЬ: Управление проигрыванием симуляции и хранение оптимизированных операций.
 * ДОЛЖЕН СОДЕРЖАТЬ: optimizedOperations, simulationStep, isSimulating, таймер симуляции.
 * НЕ ДОЛЖЕН СОДЕРЖАТЬ: JSX или персистентные настройки оптимизатора.
 */
import { useState, useEffect, useRef } from 'react';
import { PunchOp } from '../types';

export const useSimulationState = () => {
    const [optimizedOperations, setOptimizedOperations] = useState<PunchOp[] | null>(null);
    const [simulationStep, setSimulationStep] = useState<number>(0);
    const [isSimulating, setIsSimulating] = useState<boolean>(false);
    const [simulationSpeed, setSimulationSpeed] = useState<number>(50);
    const simulationInterval = useRef<number | null>(null);

    useEffect(() => {
        if (isSimulating && optimizedOperations) {
            simulationInterval.current = window.setInterval(() => {
                setSimulationStep(prev => {
                    if (prev >= optimizedOperations.length - 1) {
                        setIsSimulating(false);
                        return prev;
                    }
                    return prev + 1;
                });
            }, simulationSpeed);
        } else {
            if (simulationInterval.current) {
                clearInterval(simulationInterval.current);
                simulationInterval.current = null;
            }
        }
        return () => {
            if (simulationInterval.current) clearInterval(simulationInterval.current);
        };
    }, [isSimulating, optimizedOperations, simulationSpeed]);

    const stopSimulation = () => { 
        setIsSimulating(false); 
        setSimulationStep(0); 
    };

    const stepSimulation = (val: number) => {
        setIsSimulating(false);
        if (optimizedOperations) {
            setSimulationStep(Math.max(0, Math.min(val, optimizedOperations.length - 1)));
        }
    };

    return {
        optimizedOperations, setOptimizedOperations,
        simulationStep, setSimulationStep,
        isSimulating, setIsSimulating,
        simulationSpeed, setSimulationSpeed,
        stopSimulation, stepSimulation
    };
};

/**
 * ОТВЕТСТВЕННОСТЬ: Состояние модальных окон и система уведомлений (тостов).
 * ДОЛЖЕН СОДЕРЖАТЬ: Состояния видимости модалок, текст G-кода, массив тостов.
 * НЕ ДОЛЖЕН СОДЕРЖАТЬ: Бизнес-логику генерации контента.
 */
import { useState } from 'react';
import { ToastMessage } from '../types';
import { generateId } from '../utils/helpers';

export const useUIState = () => {
    const [toasts, setToasts] = useState<ToastMessage[]>([]);
    const [showGCodeModal, setShowGCodeModal] = useState(false);
    const [showOptimizerModal, setShowOptimizerModal] = useState(false);
    const [showAutoPunchSettingsModal, setShowAutoPunchSettingsModal] = useState(false);
    const [showTeachSaveModal, setShowTeachSaveModal] = useState(false);
    const [isGeneratingGCode, setIsGeneratingGCode] = useState(false);
    const [generatedGCode, setGeneratedGCode] = useState('');

    const addToast = (message: string, type: ToastMessage['type']) => {
        setToasts(prev => [...prev, { id: generateId(), message, type }]);
    };
    const removeToast = (id: string) => {
        setToasts(prev => prev.filter(t => t.id !== id));
    };

    return {
        toasts, addToast, removeToast,
        showGCodeModal, setShowGCodeModal,
        showOptimizerModal, setShowOptimizerModal,
        showAutoPunchSettingsModal, setShowAutoPunchSettingsModal,
        showTeachSaveModal, setShowTeachSaveModal,
        isGeneratingGCode, setIsGeneratingGCode,
        generatedGCode, setGeneratedGCode
    };
};

/**
 * ОТВЕТСТВЕННОСТЬ: Отрисовка основного интерфейса приложения.
 * ДОЛЖЕН СОДЕРЖАТЬ: Композицию Header, Sidebar, CanvasArea, RightPanel и модальных окон.
 * НЕ ДОЛЖЕН СОДЕРЖАТЬ: React хуки или бизнес-логику.
 */
import React from 'react';
import { AppMode, Part, Tool, ManualPunchMode, SnapMode, NibbleSettings, DestructSettings, TeachCycle, ToastMessage, MachineSettings, OptimizerSettings, PunchOp, NestLayout, NestResultSheet, ScheduledPart } from './types';
import { Header } from './components/Header';
import { Sidebar } from './components/Sidebar';
import { RightPanel } from './components/RightPanel';
import { CanvasArea } from './components/CanvasArea';
import { ToolLibraryView } from './components/ToolLibraryView';
import { TurretSetupView } from './components/TurretSetupView';
import { ScriptLibraryView } from './components/ScriptLibraryView';
import { PartLibraryView } from './components/PartLibraryView';
import { MachineSetupView } from './components/MachineSetupView';
import { AutoPunchSettingsModal } from './components/AutoPunchSettingsModal';
import { GCodeModal } from './components/GCodeModal';
import { OptimizerSettingsModal } from './components/OptimizerSettingsModal';
import { TeachCycleSaveModal } from './components/TeachCycleSaveModal';
import { ConfirmationModal } from './components/common/ConfirmationModal';
import { ToastContainer } from './components/common/Toast';

interface AppUIProps {
    mode: AppMode;
    setMode: (m: AppMode) => void;
    // Data
    tools: Tool[];
    parts: Part[];
    scripts: any[];
    nests: NestLayout[];
    turretLayouts: any[];
    machineSettings: MachineSettings;
    optimizerSettings: OptimizerSettings;
    teachCycles: TeachCycle[];
    // Editor State
    activePart: Part | null;
    activePartProcessedGeometry: any;
    manualPunchMode: ManualPunchMode;
    selectedToolId: string | null;
    selectedPunchId: string | null;
    punchOrientation: number;
    snapMode: SnapMode;
    punchOffset: number;
    nibbleSettings: NibbleSettings;
    destructSettings: DestructSettings;
    teachMode: boolean;
    selectedSegmentIds: number[];
    selectedTeachPunchIds: string[];
    // Nesting State
    activeNest: NestLayout | null;
    activeSheetIndex: number;
    selectedNestPartId: string | null;
    isNestingProcessing: boolean;
    nestingProgress: number;
    nestingStatus: string;
    // Simulation
    optimizedOperations: PunchOp[] | null;
    simulationStep: number;
    isSimulating: boolean;
    simulationSpeed: number;
    // Handlers
    onGenerateGCodeRequest: () => void;
    onOptimizePathRequest: () => void;
    onRunOptimization: (s: OptimizerSettings) => void;
    onToggleSimulation: () => void;
    onStopSimulation: () => void;
    onStepSimulation: (v: number) => void;
    onSpeedChange: (v: number) => void;
    onFileUpload: (e: any) => void;
    onClearAllPunches: () => void;
    onCanvasClick: (p: any) => void;
    onTeachBulkSelect: (s: number[], p: string[], a: boolean) => void;
    onTeachModeToggle: (e: boolean) => void;
    onSaveTeachCycle: (n: string, s: any) => void;
    onDeleteTeachCycle: (id: string) => void;
    onDeletePunch: (id: string | string[]) => void;
    onUpdatePunch: (id: string, u: any) => void;
    onSavePartAsScript: () => void;
    onSavePartAsStatic: () => void;
    onRunNesting: () => void;
    onClearNest: () => void;
    onMoveNestPart: (id: string, dx: number, dy: number) => void;
    onRotateNestPart: (id: string) => void;
    onUpdateNestingSettings: (s: any, sp: ScheduledPart[]) => void;
    onUpdateNestMetadata: (m: any) => void;
    onUpdateActivePart: (u: any) => void;
    onClosePart: () => void;
    onSelectNestPart: (id: string | null) => void;
    onLoadPartFromLibrary: (p: Part) => void;
    onDeletePartFromLibrary: (id: string) => void;
    onUpdatePartInLibrary: (p: Part) => void;
    onSaveScript: (s: any) => void;
    onDeleteScript: (id: string) => void;
    onCreatePartFromScript: (p: Part) => void;
    onBatchProcess: (p: Part[], sp: ScheduledPart[]) => void;
    onSaveTool: (t: Tool) => void;
    onDeleteTool: (id: string) => void;
    onUpdateMachineSettings: (s: MachineSettings) => void;
    onUpdateTurretTools: (t: Tool[] | ((prev: Tool[]) => Tool[])) => void;
    onUpdateTurretLayouts: (l: TurretLayout[] | ((prev: TurretLayout[]) => TurretLayout[])) => void;
    // UI Helpers
    ui: {
        toasts: ToastMessage[];
        removeToast: (id: string) => void;
        showGCodeModal: boolean;
        setShowGCodeModal: (v: boolean) => void;
        showOptimizerModal: boolean;
        setShowOptimizerModal: (v: boolean) => void;
        showAutoPunchSettingsModal: boolean;
        setShowAutoPunchSettingsModal: (v: boolean) => void;
        showTeachSaveModal: boolean;
        setShowTeachSaveModal: (v: boolean) => void;
        generatedGCode: string;
        downloadGCode: () => void;
        openAutoPunchSettings: () => void;
        onAutoPunchApply: (s: any) => void;
    };
    confirmation: { state: any; close: () => void };
    panZoom: { svgRef: any; viewBox: any; setViewBox: any; isDragging: boolean; getPointFromEvent: any; handlers: any };
    manualPunchState: { step: number; points: any[] };
}

export const AppUI: React.FC<AppUIProps> = (props) => {
    const { mode, activePart, activeNest, parts, tools, ui, confirmation, panZoom } = props;
    const currentNestSheet = activeNest?.sheets[props.activeSheetIndex] || null;

    return (
        <div className="flex flex-col h-full font-sans relative">
            <Header 
                mode={mode} 
                setMode={props.setMode} 
                onGenerateGCode={props.onGenerateGCodeRequest} 
                onOptimizePath={props.onOptimizePathRequest}
                onOpenTurretConfig={() => props.setMode(AppMode.TurretSetup)}
            />

            <div className="flex flex-1 overflow-hidden">
                {(mode === AppMode.PartEditor || mode === AppMode.Nesting) ? (
                    <>
                        <Sidebar 
                            mode={mode}
                            parts={parts} 
                            activePart={activePart}
                            activePartId={activePart?.id || null}
                            setActivePartId={() => {}} 
                            onDeletePart={props.onDeletePartFromLibrary}
                            tools={tools}
                            activeNest={activeNest}
                            activeSheetIndex={props.activeSheetIndex}
                            setActiveSheetIndex={props.setActiveSheetIndex}
                            onFileUpload={props.onFileUpload}
                            manualPunchMode={props.manualPunchMode} setManualPunchMode={props.setManualPunchMode}
                            selectedToolId={props.selectedToolId} setSelectedToolId={props.setSelectedToolId}
                            selectedPunchId={props.selectedPunchId} setSelectedPunchId={props.setSelectedPunchId}
                            onDeletePunch={props.onDeletePunch} onUpdatePunch={props.onUpdatePunch}
                            onClearAllPunches={props.onClearAllPunches}
                            punchOrientation={props.punchOrientation} setPunchOrientation={props.setPunchOrientation} 
                            onCyclePunchOrientation={() => props.setPunchOrientation((props.punchOrientation+90)%360)}
                            snapMode={props.snapMode} setSnapMode={props.setSnapMode}
                            punchOffset={props.punchOffset} setPunchOffset={props.setPunchOffset}
                            onUpdateNestingSettings={props.onUpdateNestingSettings}
                            onUpdateNestMetadata={props.onUpdateNestMetadata}
                            nibbleSettings={props.nibbleSettings} setNibbleSettings={props.setNibbleSettings}
                            destructSettings={props.destructSettings} setDestructSettings={props.setDestructSettings}
                            onOpenTurretView={() => props.setMode(AppMode.TurretSetup)}
                            onSavePartAsScript={props.onSavePartAsScript}
                            onSavePartAsStatic={props.onSavePartAsStatic}
                            onUpdateActivePart={props.onUpdateActivePart}
                            onClosePart={props.onClosePart}
                            teachMode={props.teachMode} setTeachMode={props.onTeachModeToggle}
                            onSaveTeachCycle={() => ui.setShowTeachSaveModal(true)}
                            teachCycles={props.teachCycles} onDeleteTeachCycle={props.onDeleteTeachCycle}
                            onRunNesting={props.onRunNesting}
                            isNestingProcessing={props.isNestingProcessing}
                            nestingProgress={props.nestingProgress}
                            nestingStatus={props.nestingStatus}
                            onClearNest={props.onClearNest}
                            selectedNestPartId={props.selectedNestPartId}
                            onMoveNestPart={props.onMoveNestPart}
                            onRotateNestPart={props.onRotateNestPart}
                        />
                        <CanvasArea 
                            mode={mode}
                            activePart={activePart}
                            processedGeometry={props.activePartProcessedGeometry}
                            activeNest={activeNest}
                            currentNestSheet={currentNestSheet}
                            tools={tools}
                            parts={parts}
                            svgRef={panZoom.svgRef}
                            viewBox={panZoom.viewBox}
                            setViewBox={panZoom.setViewBox}
                            isDragging={panZoom.isDragging}
                            getPointFromEvent={panZoom.getPointFromEvent}
                            panZoomHandlers={panZoom.handlers}
                            onOpenAutoPunchSettings={ui.openAutoPunchSettings}
                            punchCreationStep={props.manualPunchState.step}
                            punchCreationPoints={props.manualPunchState.points}
                            manualPunchMode={props.manualPunchMode}
                            selectedToolId={props.selectedToolId}
                            selectedPunchId={props.selectedPunchId}
                            onSelectPunch={props.setSelectedPunchId}
                            placementReference={0 as any} // Mock, not really used in CanvasArea props but interface expects it
                            placementSide={0 as any}
                            punchOrientation={props.punchOrientation}
                            snapMode={props.snapMode}
                            punchOffset={props.punchOffset}
                            nibbleSettings={props.nibbleSettings}
                            teachMode={props.teachMode}
                            selectedSegmentIds={props.selectedSegmentIds}
                            selectedTeachPunchIds={props.selectedTeachPunchIds}
                            onTeachBulkSelect={props.onTeachBulkSelect}
                            selectedNestPartId={props.selectedNestPartId}
                            onSelectNestPart={props.onSelectNestPart}
                            onMoveNestPart={props.onMoveNestPart}
                            optimizedOperations={props.optimizedOperations}
                            simulationStep={props.simulationStep}
                        />
                        <RightPanel 
                            tools={tools}
                            selectedToolId={props.selectedToolId}
                            setSelectedToolId={props.setSelectedToolId}
                            onOpenTurretView={() => props.setMode(AppMode.TurretSetup)}
                            isNestingMode={mode === AppMode.Nesting}
                            activeNest={activeNest}
                            activeSheetIndex={props.activeSheetIndex}
                            setActiveSheetIndex={props.setActiveSheetIndex}
                            allParts={parts}
                            simulationStep={props.simulationStep}
                            totalSimulationSteps={props.optimizedOperations ? props.optimizedOperations.length : 0}
                            isSimulating={props.isSimulating}
                            simulationSpeed={props.simulationSpeed}
                            onToggleSimulation={props.onToggleSimulation}
                            onStopSimulation={props.onStopSimulation}
                            onStepChange={props.onStepSimulation}
                            onSpeedChange={props.onSpeedChange}
