                            setSelectedToolId={props.setSelectedToolId}
                            onOpenTurretView={() => props.setMode(AppMode.TurretSetup)}
                            isNestingMode={mode === AppMode.Nesting}
                            activeNest={activeNest}
                            activeSheetIndex={props.activeSheetIndex}
                            setActiveSheetIndex={props.setActiveSheetIndex}
                            allParts={parts}
                            simulationStep={props.simulationStep}
                            totalSimulationSteps={props.optimizedOperations ? props.optimizedOperations.length : 0}
                            isSimulating={props.isSimulating}
                            simulationSpeed={props.simulationSpeed}
                            onToggleSimulation={props.onToggleSimulation}
                            onStopSimulation={props.onStopSimulation}
                            onStepChange={props.onStepSimulation}
                            onSpeedChange={props.onSpeedChange}
                            optimizedOperations={props.optimizedOperations}
                        />
                    </>
                ) : (
                    mode === AppMode.PartLibrary ? (
                        <PartLibraryView 
                            parts={parts} 
                            tools={tools}
                            onLoadPart={props.onLoadPartFromLibrary}
                            onDeletePart={props.onDeletePartFromLibrary}
                            onUpdatePart={props.onUpdatePartInLibrary}
                        />
                    ) : mode === AppMode.ScriptLibrary ? (
                        <ScriptLibraryView 
                            scripts={props.scripts} 
                            tools={tools} 
                            parts={parts}
                            onSaveScript={props.onSaveScript}
                            onDeleteScript={props.onDeleteScript}
                            onCreatePart={props.onCreatePartFromScript}
                            onBatchProcess={props.onBatchProcess}
                        />
                    ) : mode === AppMode.ToolLibrary ? (
                        <ToolLibraryView 
                            tools={tools} 
                            onSaveTool={props.onSaveTool} 
                            onDeleteTool={props.onDeleteTool} 
                        />
                    ) : mode === AppMode.TurretSetup ? (
                        <TurretSetupView 
                            tools={tools} 
                            setTools={props.onUpdateTurretTools} 
                            layouts={props.turretLayouts} 
                            setLayouts={props.onUpdateTurretLayouts} 
                        />
                    ) : mode === AppMode.MachineSetup ? (
                        <MachineSetupView 
                            settings={props.machineSettings} 
                            onUpdate={props.onUpdateMachineSettings} 
                        />
                    ) : null
                )}
            </div>

            {/* Модальные окна */}
            {ui.showAutoPunchSettingsModal && activePart && (
                <AutoPunchSettingsModal 
                    onClose={() => ui.setShowAutoPunchSettingsModal(false)}
                    onApply={ui.onAutoPunchApply}
                    turretLayouts={props.turretLayouts}
                />
            )}
            {ui.showTeachSaveModal && <TeachCycleSaveModal onClose={() => ui.setShowTeachSaveModal(false)} onSave={props.onSaveTeachCycle} />}

            {ui.showOptimizerModal && (
                <OptimizerSettingsModal
                    initialSettings={props.optimizerSettings}
                    onClose={() => ui.setShowOptimizerModal(false)}
                    onGenerate={props.onRunOptimization}
                />
            )}

            {ui.showGCodeModal && (
                <GCodeModal 
                    gcode={ui.generatedGCode} 
                    onClose={() => ui.setShowGCodeModal(false)} 
                    onDownload={ui.downloadGCode}
                    sheet={currentNestSheet || undefined}
                    parts={parts}
                    tools={tools}
                    clampPositions={activeNest?.settings.clampPositions}
                    scheduledParts={activeNest?.scheduledParts}
                    nestName={activeNest?.workOrder ? `${activeNest.workOrder}_${props.activeSheetIndex + 1}.nc` : `Program_${props.activeSheetIndex + 1}.nc`}
                    allSheets={activeNest?.sheets}
                />
            )}

            <ToastContainer toasts={ui.toasts} removeToast={ui.removeToast} />
            <ConfirmationModal state={confirmation.state} onCancel={confirmation.close} />
        </div>
    );
};

/**
 * Finn-Power CAD/CAM Studio
 * ОТВЕТСТВЕННОСТЬ: Корневой компонент. Только оркестрация хуков и UI.
 */
import React from 'react';
import { useAppLogic } from './hooks/useAppLogic';
import { AppUI } from './AppUI';
import { AppMode, ScheduledPart, Part, Tool } from './types';
import { generateId, getPartBaseName, generatePartNameFromProfile } from './utils/helpers';
// FIX: Added missing import for generateParametricScript
import { generateParametricScript } from './services/scriptGenerator';

const App: React.FC = () => {
    const app = useAppLogic();
    const { persistence, editor, nesting, simulation, ui, handlers, derived } = app;

    // Вспомогательная обертка для проброса всех необходимых пропсов в AppUI
    // Это позволяет AppUI оставаться чистым компонентом представления.
    return (
        <AppUI 
            // Core
            mode={app.mode} 
            setMode={app.setMode}

            // Data
            tools={persistence.tools} 
            parts={persistence.parts} 
            scripts={persistence.scripts} 
            nests={persistence.nests}
            turretLayouts={persistence.turretLayouts} 
            machineSettings={persistence.machineSettings}
            optimizerSettings={persistence.optimizerSettings} 
            teachCycles={persistence.teachCycles}

            // Editor
            activePart={editor.activePart} 
            activePartProcessedGeometry={editor.activePartProcessedGeometry}
            manualPunchMode={editor.manualPunchMode} 
            selectedToolId={editor.selectedToolId} 
            selectedPunchId={editor.selectedPunchId}
            punchOrientation={editor.punchOrientation} 
            snapMode={editor.snapMode} 
            punchOffset={editor.punchOffset}
            nibbleSettings={editor.nibbleSettings} 
            destructSettings={editor.destructSettings} 
            teachMode={editor.teachMode}
            selectedSegmentIds={editor.selectedSegmentIds} 
            selectedTeachPunchIds={editor.selectedTeachPunchIds}

            // Nesting
            activeNest={derived.activeNest} 
            activeSheetIndex={nesting.activeSheetIndex} 
            selectedNestPartId={nesting.selectedNestPartId}
            isNestingProcessing={nesting.isNestingProcessing} 
            nestingProgress={nesting.nestingProgress} 
            nestingStatus={nesting.nestingStatus}

            // Simulation
            optimizedOperations={simulation.optimizedOperations} 
            simulationStep={simulation.simulationStep}
            isSimulating={simulation.isSimulating} 
            simulationSpeed={simulation.simulationSpeed}

            // Handlers
            onGenerateGCodeRequest={handlers.onGenerateGCodeRequest}
            onOptimizePathRequest={handlers.onOptimizePathRequest}
            onRunOptimization={handlers.onRunOptimization}
            onToggleSimulation={() => simulation.setIsSimulating(!simulation.isSimulating)}
            onStopSimulation={simulation.stopSimulation}
            onStepSimulation={simulation.stepSimulation}
            onSpeedChange={simulation.setSimulationSpeed}
            onFileUpload={handlers.handleFileUpload}
            onClearAllPunches={handlers.onClearAllPunches}
            onCanvasClick={app.panZoom.panZoomHandlers.onMouseUp as any} // Fallback proxy
            onTeachBulkSelect={(segs, punches, add) => { 
                if (add) { 
                    editor.setSelectedSegmentIds(prev => Array.from(new Set([...prev, ...segs]))); 
                    editor.setSelectedTeachPunchIds(prev => Array.from(new Set([...prev, ...punches]))); 
                } else { 
                    editor.setSelectedSegmentIds(segs); 
                    editor.setSelectedTeachPunchIds(punches); 
                }
            }}
            onTeachModeToggle={(val) => { editor.setTeachMode(val); editor.setSelectedSegmentIds([]); editor.setSelectedTeachPunchIds([]); }}
            onSaveTeachCycle={handlers.onSaveTeachCycle}
            onDeleteTeachCycle={(id) => persistence.setTeachCycles(prev => prev.filter(c => c.id !== id))}
            onDeletePunch={(ids) => editor.setActivePart(p => p ? {...p, punches: p.punches.filter(px => !(Array.isArray(ids) ? ids.includes(px.id) : px.id === ids))} : null)}
            onUpdatePunch={(id, u) => editor.setActivePart(p => p ? {...p, punches: p.punches.map(px => px.id === id ? {...px, ...u} : px)} : null)}
            onSavePartAsScript={() => { const code = generateParametricScript(editor.activePart!, persistence.tools); persistence.setScripts(s => [...s, {id: generateId(), name: editor.activePart!.name, code, defaultWidth: editor.activePart!.faceWidth, defaultHeight: editor.activePart!.faceHeight, updatedAt: Date.now()}]); editor.setActivePart(null); ui.addToast("Скрипт сохранен", "success"); }}
            onSavePartAsStatic={() => { const name = generatePartNameFromProfile(getPartBaseName(editor.activePart!.name), editor.activePart!.profile, editor.activePart!.faceWidth, editor.activePart!.faceHeight); persistence.setParts(prev => [...prev.filter(x=>x.id!==editor.activePart!.id), {...editor.activePart!, name}]); editor.setActivePart(null); ui.addToast(`Деталь ${name} сохранена`, "success"); }}
            onRunNesting={handlers.handleRunNesting}
            onClearNest={() => app.confirmation.confirm("Сброс", "Очистить раскрой?", () => { persistence.setNests(n => n.map(x => x.id === nesting.activeNestId ? {...x, sheets: []} : x)); nesting.setSelectedNestPartId(null); nesting.setActiveSheetIndex(0); })}
            onMoveNestPart={(id, dx, dy) => { 
                const newSheets = [...derived.activeNest!.sheets]; 
                newSheets[nesting.activeSheetIndex] = {...derived.currentNestSheet!, placedParts: derived.currentNestSheet!.placedParts.map(p => p.id === id ? {...p, x: p.x+dx, y: p.y+dy} : p)};
                persistence.setNests(n => n.map(x => x.id === nesting.activeNestId ? {...x, sheets: newSheets} : x));
            }}
            onRotateNestPart={(id) => {
                const newSheets = [...derived.activeNest!.sheets];
                newSheets[nesting.activeSheetIndex] = { ...derived.currentNestSheet!, placedParts: derived.currentNestSheet!.placedParts.map(pp => {
                    if(pp.id !== id) return pp;
                    const pDef = persistence.parts.find(p=>p.id===pp.partId)!;
                    const w = pDef.geometry.width, h = pDef.geometry.height;
                    const oldR = pp.rotation * Math.PI / 180, newR = ((pp.rotation+90)%360) * Math.PI / 180;
                    const cxOld = (w/2)*Math.cos(oldR)-(h/2)*Math.sin(oldR), cyOld = (w/2)*Math.sin(oldR)+(h/2)*Math.cos(oldR);
                    const cxNew = (w/2)*Math.cos(newR)-(h/2)*Math.sin(newR), cyNew = (w/2)*Math.sin(newR)+(h/2)*Math.cos(newR);
                    return {...pp, rotation: (pp.rotation+90)%360, x: pp.x + (cxOld-cxNew), y: pp.y + (cyOld-cyNew)};
                })};
                persistence.setNests(n => n.map(x => x.id === nesting.activeNestId ? {...x, sheets: newSheets} : x));
            }}
            onUpdateNestingSettings={(s, sp) => persistence.setNests(prev => prev.map(n => n.id === nesting.activeNestId ? { ...n, settings: s, scheduledParts: sp } : n))}
            onUpdateNestMetadata={(m) => persistence.setNests(prev => prev.map(n => n.id === nesting.activeNestId ? { ...n, ...m } : n))}
            onUpdateActivePart={(u) => editor.setActivePart(p => p ? {...p, ...u} : null)}
            onClosePart={() => app.confirmation.confirm("Закрыть?", "Изменения будут потеряны.", () => editor.setActivePart(null))}
            onSelectNestPart={nesting.setSelectedNestPartId}
            onLoadPartFromLibrary={(p) => { editor.setActivePart(p); app.setMode(AppMode.PartEditor); }}
            onDeletePartFromLibrary={(id) => app.confirmation.confirm("Удаление", "Удалить деталь?", () => { persistence.setParts(p => p.filter(x => x.id !== id)); persistence.setNests(n => n.map(x => ({...x, scheduledParts: x.scheduledParts.filter(s => s.partId !== id)}))); })}
            onUpdatePartInLibrary={(p) => { persistence.setParts(prev => prev.map(px => px.id === p.id ? p : px)); ui.addToast("Обновлено", "success"); }}
            onSaveScript={(s) => { persistence.setScripts(prev => prev.map(sx => sx.id === s.id ? s : sx)); ui.addToast("Обновлено", "success"); }}
            onDeleteScript={(id) => app.confirmation.confirm("Удаление", "Удалить скрипт?", () => persistence.setScripts(prev => prev.filter(s => s.id !== id)))}
            onCreatePartFromScript={(p) => { persistence.setParts(prev => [...prev, p]); ui.addToast("Создано", "success"); }}
            onBatchProcess={(pNew, spNew) => { 
                persistence.setParts(prev => [...prev, ...pNew.filter(pn => !prev.some(px => px.id === pn.id))]);
                if (nesting.activeNestId) { persistence.setNests(prev => prev.map(n => n.id === nesting.activeNestId ? { ...n, scheduledParts: [...n.scheduledParts, ...spNew] } : n)); }
            }}
            onSaveTool={(t) => { persistence.setTools(prev => prev.some(px => px.id === t.id) ? prev.map(px => px.id === t.id ? t : px) : [...prev, t]); ui.addToast("Сохранено", "success"); }}
            onDeleteTool={(id) => app.confirmation.confirm("Удаление", "Удалить инструмент?", () => persistence.setTools(prev => prev.filter(t => t.id !== id)))}
            onUpdateMachineSettings={persistence.setMachineSettings}
            onUpdateTurretTools={persistence.setTools}
            onUpdateTurretLayouts={persistence.setTurretLayouts}

            // UI States
            ui={{
                ...ui,
                downloadGCode: handlers.downloadGCode,
                openAutoPunchSettings: () => ui.setShowAutoPunchSettingsModal(true),
                onAutoPunchApply: handlers.onAutoPunchApply
            }}
            confirmation={{ state: app.confirmation.state, close: app.confirmation.close }}
            panZoom={{ ...app.panZoom, handlers: app.panZoom.panZoomHandlers }}
            manualPunchState={{ step: editor.manualPunch.punchCreationStep, points: editor.manualPunch.punchCreationPoints }}
            setActiveSheetIndex={nesting.setActiveSheetIndex}
            // FIX: Removed duplicate manualPunchMode prop (previously here)
            setManualPunchMode={editor.setManualPunchMode}
            setSelectedToolId={editor.setSelectedToolId}
            setSelectedPunchId={editor.setSelectedPunchId}
            setPunchOrientation={editor.setPunchOrientation}
            setSnapMode={editor.setSnapMode}
            setPunchOffset={editor.setPunchOffset}
            setNibbleSettings={editor.setNibbleSettings}
            setDestructSettings={editor.setDestructSettings}
        />
    );
};

export default App;

/**
 * ОТВЕТСТВЕННОСТЬ: Управление временным состоянием настроек раскроя до нажатия "OK".
 * ДОЛЖЕН СОДЕРЖАТЬ: Логику обновления настроек, списка деталей и смены вкладок.
 */
import { useState } from 'react';
import { NestLayout, ScheduledPart, NestingSettings } from '../types';

export const useNestingModalState = (activeNest: NestLayout) => {
    const [activeTab, setActiveTab] = useState<'global' | 'parts' | 'sheet'>('sheet');
    const [settings, setSettings] = useState<NestingSettings>(() => 
        JSON.parse(JSON.stringify(activeNest.settings))
    );
    const [scheduledParts, setScheduledParts] = useState<ScheduledPart[]>(() => 
        JSON.parse(JSON.stringify(activeNest.scheduledParts))
    );

    const updateSettings = (updates: Partial<NestingSettings>) => {
        setSettings(prev => ({ ...prev, ...updates }));
    };

    return {
        activeTab, setActiveTab,
        settings, setSettings,
        updateSettings,
        scheduledParts, setScheduledParts
    };
};

/**
 * ОТВЕТСТВЕННОСТЬ: Интерфейс для настройки отступов, прижимов и упоров.
 */
import React from 'react';
import { NestingSettings } from '../../types';
import { ModalInputField } from '../common/InputField';

const STOP_DEFINITIONS: Record<number, { min: number, max: number, label: string }> = {
    1: { min: 420, max: 2080, label: 'Упор 1 (Стандарт)' },
    2: { min: 83, max: 1743, label: 'Упор 2 (L <= 1900)' },
    3: { min: 0, max: 1660, label: 'Упор 3 (L <= 1360)' },
    4: { min: 0, max: 1660, label: 'Упор 4 (L < 750)' },
};

const resolveAutoStop = (width: number) => {
    if (width < 750) return 4;
    if (width <= 1360) return 3;
    if (width <= 1900) return 2;
    return 1;
};

interface GlobalParametersTabProps {
    settings: NestingSettings;
    updateSettings: (u: Partial<NestingSettings>) => void;
}

export const GlobalParametersTab: React.FC<GlobalParametersTabProps> = ({ settings, updateSettings }) => {
    const activeSheet = settings.availableSheets.find(s => s.id === settings.activeSheetId) || settings.availableSheets[0];
    const sheetWidth = activeSheet ? activeSheet.width : 2560;
    const activeStopId = settings.loadingStopId === 0 ? resolveAutoStop(sheetWidth) : settings.loadingStopId;
    const activeStopInfo = STOP_DEFINITIONS[activeStopId];

    const updateClamp = (index: number, value: string) => {
        const newClamps = [...settings.clampPositions];
        newClamps[index] = parseFloat(value) || 0;
        updateSettings({ clampPositions: newClamps });
    };

    const validateClamp = (pos: number, index: number, allClamps: number[]): string | null => {
        if (!pos) return null;
        if (pos < activeStopInfo.min || pos > activeStopInfo.max) return `Выход за пределы (${activeStopInfo.min}-${activeStopInfo.max})`;
        for (let i = 0; i < allClamps.length; i++) {
            if (i === index || !allClamps[i]) continue;
            if (Math.abs(pos - allClamps[i]) < 150) return `Конфликт с зажимом ${i+1} (<150мм)`;
        }
        return null;
    };

    return (
        <div className="grid grid-cols-2 gap-x-8 gap-y-4">
            <div className="space-y-4">
                <fieldset className="border border-gray-600 p-3 rounded-md">
                    <legend className="px-2 font-semibold text-gray-300 text-sm">Отступы между деталями</legend>
                    <div className="flex space-x-4">
                        <ModalInputField label="По X (мм)" type="number" value={settings.partSpacingX} onChange={e => updateSettings({partSpacingX: parseFloat(e.target.value) || 0})} />
                        <ModalInputField label="По Y (мм)" type="number" value={settings.partSpacingY} onChange={e => updateSettings({partSpacingY: parseFloat(e.target.value) || 0})} />
                    </div>
                </fieldset>
                <fieldset className="border border-gray-600 p-3 rounded-md">
                    <legend className="px-2 font-semibold text-gray-300 text-sm">Поля листа</legend>
                    <div className="grid grid-cols-2 gap-4">
                        {(['sheetMarginTop', 'sheetMarginBottom', 'sheetMarginLeft', 'sheetMarginRight'] as const).map(field => (
                            <ModalInputField key={field} label={field.replace('sheetMargin', '')} type="number" value={settings[field]} onChange={e => updateSettings({ [field]: parseFloat(e.target.value) || 0 })} />
                        ))}
                    </div>
                </fieldset>
            </div>
            <div className="space-y-4">
                <fieldset className="border border-gray-600 p-3 rounded-md">
                    <legend className="px-2 font-semibold text-gray-300 text-sm">Прижимы и Упоры</legend>
                    <div className="mb-4 bg-gray-700/30 p-2 rounded">
                        <label className="block text-sm font-medium text-gray-300 mb-1">Выбор Упора</label>
                        <select value={settings.loadingStopId} onChange={(e) => updateSettings({ loadingStopId: parseInt(e.target.value) })} className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-sm text-gray-200">
                            <option value={0}>Автоматически</option>
                            {[1, 2, 3, 4].map(id => <option key={id} value={id}>{STOP_DEFINITIONS[id].label}</option>)}
                        </select>
                    </div>
                    <div className="grid grid-cols-3 gap-2">
                        {settings.clampPositions.map((c, i) => (
                            <div key={i}>
                                <ModalInputField label={`Поз. ${i+1}`} type="number" value={c || ''} onChange={e => updateClamp(i, e.target.value)} />
                                {validateClamp(c, i, settings.clampPositions) && <p className="text-[10px] text-red-400 mt-1">{validateClamp(c, i, settings.clampPositions)}</p>}
                            </div>
                        ))}
                    </div>
                </fieldset>
                <fieldset className="border border-gray-600 p-3 rounded-md">
                    <legend className="px-2 font-semibold text-gray-300 text-sm">Направление</legend>
                    <div className="grid grid-cols-3 gap-1 w-24 mx-auto">
                        {[6, 7, 8, 3, 4, 5, 0, 1, 2].map(i => (
                            <label key={i} className={`flex items-center justify-center w-6 h-6 rounded-full cursor-pointer ${settings.nestingDirection === i ? 'bg-blue-500' : 'bg-gray-700'}`}>
                                <input type="radio" name="dir" value={i} checked={settings.nestingDirection === i} onChange={() => updateSettings({nestingDirection: i})} className="hidden" />
                            </label>
                        ))}
                    </div>
                </fieldset>
            </div>
        </div>
    );
};

/**
 * ОТВЕТСТВЕННОСТЬ: Выбор деталей из библиотеки и настройка их количества/вращения.
 */
import React from 'react';
import { Part, ScheduledPart, NestingConstraints } from '../../types';
import { PlusIcon, TrashIcon } from '../Icons';

interface PartListTabProps {
    allParts: Part[];
    scheduledParts: ScheduledPart[];
    setScheduledParts: React.Dispatch<React.SetStateAction<ScheduledPart[]>>;
}

export const PartListTab: React.FC<PartListTabProps> = ({ allParts, scheduledParts, setScheduledParts }) => {
    const addPart = (partId: string) => {
        setScheduledParts(prev => {
            const existing = prev.find(p => p.partId === partId);
            if (existing) return prev.map(p => p.partId === partId ? { ...p, quantity: p.quantity + 1 } : p);
            const part = allParts.find(p => p.id === partId);
            return [...prev, { partId, quantity: 1, nesting: part?.nesting || { allow0_180: true, allow90_270: true, initialRotation: 0, commonLine: false, canMirror: false } }];
        });
    };

    const updatePart = (partId: string, updates: Partial<ScheduledPart> | { nesting: Partial<NestingConstraints> }) => {
        setScheduledParts(prev => prev.map(p => {
            if (p.partId !== partId) return p;
            if ('nesting' in updates) return { ...p, nesting: { ...p.nesting, ...updates.nesting } };
            return { ...p, ...updates };
        }));
    };

    return (
        <div className="grid grid-cols-3 gap-x-8">
            <div className="col-span-1">
                <h3 className="font-semibold text-gray-300 mb-2 text-sm">Библиотека</h3>
                <div className="bg-gray-900/50 rounded-md p-2 h-80 overflow-y-auto space-y-2">
                    {allParts.map(part => (
                        <div key={part.id} className="bg-gray-700 p-2 rounded flex items-center justify-between text-xs">
                            <span className="truncate flex-1">{part.name}</span>
                            <button onClick={() => addPart(part.id)} className="p-1 bg-blue-600 rounded-full hover:bg-blue-500"><PlusIcon className="w-3 h-3" /></button>
                        </div>
                    ))}
                </div>
            </div>
            <div className="col-span-2">
                <h3 className="font-semibold text-gray-300 mb-2 text-sm">Очередь раскроя</h3>
                <div className="bg-gray-900/50 rounded-md p-2 h-80 overflow-y-auto space-y-2">
                    <div className="grid grid-cols-[1fr,60px,40px,40px,40px,30px] gap-2 text-[10px] text-gray-500 font-bold px-2 uppercase">
                        <span>Деталь</span><span>Кол</span><span>0°</span><span>90°</span><span>Зерк</span><span></span>
                    </div>
                    {scheduledParts.map(sp => (
                        <div key={sp.partId} className="bg-gray-700 p-2 rounded grid grid-cols-[1fr,60px,40px,40px,40px,30px] items-center gap-2 text-xs">
                            <span className="truncate">{allParts.find(p => p.id === sp.partId)?.name || '...'}</span>
                            <input type="number" value={sp.quantity} onChange={e => updatePart(sp.partId, { quantity: parseInt(e.target.value) || 1 })} className="bg-gray-800 border-gray-600 rounded px-1 text-center" />
                            <input type="checkbox" checked={sp.nesting.allow0_180} onChange={e => updatePart(sp.partId, { nesting: { allow0_180: e.target.checked } })} className="mx-auto" />
                            <input type="checkbox" checked={sp.nesting.allow90_270} onChange={e => updatePart(sp.partId, { nesting: { allow90_270: e.target.checked } })} className="mx-auto" />
                            <input type="checkbox" checked={sp.nesting.canMirror} onChange={e => updatePart(sp.partId, { nesting: { canMirror: e.target.checked } })} className="mx-auto" />
                            <button onClick={() => setScheduledParts(prev => prev.filter(p => p.partId !== sp.partId))} className="text-gray-500 hover:text-red-500"><TrashIcon className="w-4 h-4" /></button>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

/**
