/**
 * ОТВЕТСТВЕННОСТЬ: Отображение доступных инструментов и их фильтрация по совместимости с выбранной станцией.
 */
import React from 'react';
import { Tool, StationConfig } from '../../types';
import { ToolPreview } from '../common/ToolDisplay';

interface TurretLibraryPanelProps {
    tools: Tool[];
    selectedStation: StationConfig | undefined;
    isMtView: boolean;
    selectedMtSlotId: number | null;
    onMount: (tool: Tool, mtIdx?: number) => void;
}

export const TurretLibraryPanel: React.FC<TurretLibraryPanelProps> = (props) => {
    const { tools, selectedStation, isMtView, selectedMtSlotId } = props;

    return (
        <div className="flex-1 overflow-hidden flex flex-col">
            <div className="p-2 bg-gray-900 border-b border-gray-700">
                <h4 className="text-xs font-bold text-gray-400 uppercase">Библиотека доступных</h4>
            </div>
            <div className="flex-1 overflow-y-auto p-2 space-y-2 custom-scrollbar">
                 {tools.map(tool => {
                     const displaySize = (tool.stationType === 'MT' || tool.name.startsWith('MT')) ? 'MT' : tool.toolSize;
                     let isCompatible = false;
                     if (selectedStation) {
                         if (isMtView) isCompatible = tool.stationType === 'MT'; 
                         else if (selectedStation.type === 'MT') isCompatible = false; 
                         else isCompatible = tool.toolSize === selectedStation.type;
                     }

                     const canMount = isCompatible && ((!isMtView && selectedStation) || (isMtView && selectedMtSlotId));

                     return (
                        <div key={tool.id} className={`bg-gray-700 p-2 rounded flex flex-col group border border-transparent ${isCompatible ? 'hover:border-blue-400' : 'opacity-40 grayscale'}`}>
                            <div className="flex items-center space-x-2">
                                <div className="w-8 h-8 bg-white rounded flex-shrink-0"><ToolPreview tool={tool} /></div>
                                <div className="overflow-hidden flex-1">
                                    <div className="font-bold text-sm text-white truncate">{tool.name}</div>
                                    <div className="flex justify-between text-xs text-gray-400">
                                        <span>{tool.shape} {tool.width}x{tool.height}</span>
                                        <span className={`font-bold ${displaySize === 'MT' ? 'text-purple-400' : 'text-yellow-400'}`}>{displaySize}</span>
                                    </div>
                                </div>
                            </div>

                            {canMount && (
                                <div className="mt-2">
                                    <button 
                                        onClick={() => props.onMount(tool, isMtView && selectedMtSlotId ? selectedMtSlotId : 0)}
                                        className={`w-full text-white text-xs py-1 rounded ${isMtView ? 'bg-purple-600 hover:bg-purple-500' : 'bg-blue-600 hover:bg-blue-500'}`}
                                    >
                                        {isMtView ? `В слот ${selectedMtSlotId}` : "Установить"}
                                    </button>
                                </div>
                            )}
                        </div>
                     );
                 })}
                 {tools.length === 0 && <div className="text-center text-gray-500 text-sm mt-4 italic">Нет свободных инструментов</div>}
            </div>
        </div>
    );
};

/**
 * ОТВЕТСТВЕННОСТЬ: Корневой компонент настройки револьвера.
 * Собирает визуализацию и боковую панель управления.
 */
import React from 'react';
import { Tool, TurretLayout, StationConfig } from '../types';
import { TurretVisualizer, MtVisualizer } from './common/TurretVisualizer';
import { useTurretLogic } from '../hooks/turret/useTurretLogic';
import { TurretLayoutManager } from './turret/TurretLayoutManager';
import { StationControlPanel } from './turret/StationControlPanel';
import { TurretLibraryPanel } from './turret/TurretLibraryPanel';

interface TurretSetupViewProps {
    tools: Tool[];
    setTools: React.Dispatch<React.SetStateAction<Tool[]>>;
    layouts: TurretLayout[];
    setLayouts: React.Dispatch<React.SetStateAction<TurretLayout[]>>;
}

export const TurretSetupView: React.FC<TurretSetupViewProps> = (props) => {
    const turret = useTurretLogic(props);
    const { 
        currentStations, selectedStationId, isMtView, selectedMtSlotId, 
        toolsOnTurret, availableTools, setIsMtView, setSelectedMtSlotId
    } = turret;

    const selectedStation = currentStations.find(s => s.id === selectedStationId);
    const activeTool = isMtView 
        ? toolsOnTurret.find(t => t.stationNumber === selectedStationId && t.mtIndex === selectedMtSlotId)
        : (selectedStation ? toolsOnTurret.find(t => t.stationNumber === selectedStation.id && !t.mtIndex) : undefined);

    const mtTools = isMtView ? toolsOnTurret.filter(t => t.stationNumber === selectedStationId) : [];

    return (
        <div className="flex h-full w-full bg-gray-100 text-gray-900 font-sans">
            {/* Левая часть: Визуализация (SVG) */}
            <div className="flex-1 relative bg-gray-300 shadow-inner overflow-hidden flex items-center justify-center">
                 {isMtView ? (
                    <div className="w-full h-full flex flex-col relative p-8">
                        <button onClick={() => setIsMtView(false)} className="absolute top-4 left-4 bg-gray-600 hover:bg-gray-500 text-white px-3 py-1 rounded shadow text-sm transition-colors z-10">
                            &larr; Назад к револьверу
                        </button>
                        <MtVisualizer 
                            tools={mtTools}
                            selectedSlotId={selectedMtSlotId}
                            onSlotClick={setSelectedMtSlotId}
                        />
                    </div>
                 ) : (
                    <div className="w-full h-full p-8">
                        <TurretVisualizer 
                            stations={currentStations}
                            tools={toolsOnTurret}
                            selectedStationId={selectedStationId}
                            onStationClick={turret.handleStationClick}
                            mode="setup"
                        />
                    </div>
                 )}
            </div>

            {/* Правая часть: Панель управления */}
            <div className="w-96 bg-gray-800 text-gray-100 flex flex-col border-l border-gray-700 shadow-xl z-10">
                <TurretLayoutManager 
                    layouts={props.layouts}
                    activeLayoutId={turret.activeLayoutId}
                    onLoad={turret.loadLayout}
                    onDelete={turret.deleteLayout}
                    newName={turret.newLayoutName}
                    setNewName={turret.setNewLayoutName}
                    onSave={turret.saveLayout}
                />

                <StationControlPanel 
                    selectedStation={selectedStation}
                    isMtView={isMtView}
                    selectedMtSlotId={selectedMtSlotId}
                    activeTool={activeTool}
                    onUpdateStation={turret.updateStationConfig}
                    onUpdateRotation={turret.updateToolRotation}
                    onUnmount={turret.handleUnmountTool}
                    onOpenMt={() => { setIsMtView(true); setSelectedMtSlotId(1); }}
                />

                <TurretLibraryPanel 
                    tools={availableTools}
                    selectedStation={selectedStation}
                    isMtView={isMtView}
                    selectedMtSlotId={selectedMtSlotId}
                    onMount={turret.handleMountTool}
                />
            </div>
        </div>
    );
};

/**
 * ОТВЕТСТВЕННОСТЬ: Управление логикой револьвера.
 * Содержит: выбор станций, установку/снятие инструмента, проверку совместимости станций и управление конфигурациями (layouts).
 */
// FIX: Added React to imports to resolve 'Cannot find namespace React' errors in UseTurretLogicProps
import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Tool, TurretLayout, StationConfig } from '../../types';
import { generateId } from '../../utils/helpers';

interface UseTurretLogicProps {
    tools: Tool[];
    setTools: React.Dispatch<React.SetStateAction<Tool[]>>;
    layouts: TurretLayout[];
    setLayouts: React.Dispatch<React.SetStateAction<TurretLayout[]>>;
}

export const useTurretLogic = ({ tools, setTools, layouts, setLayouts }: UseTurretLogicProps) => {
    const [activeLayoutId, setActiveLayoutId] = useState<string>(layouts[0]?.id || '');
    const [currentStations, setCurrentStations] = useState<StationConfig[]>(layouts[0]?.stations || []);
    const [selectedStationId, setSelectedStationId] = useState<number | null>(null);
    const [isMtView, setIsMtView] = useState(false);
    const [selectedMtSlotId, setSelectedMtSlotId] = useState<number | null>(null);
    const [newLayoutName, setNewLayoutName] = useState('');

    useEffect(() => {
        const layout = layouts.find(l => l.id === activeLayoutId);
        if (layout) {
            setCurrentStations(layout.stations);
        }
    }, [activeLayoutId, layouts]);

    const toolsOnTurret = useMemo(() => tools.filter(t => t.stationNumber !== 0 && t.stationNumber !== undefined), [tools]);
    const availableTools = useMemo(() => tools.filter(t => !t.stationNumber), [tools]);

    const loadLayout = useCallback((layoutId: string) => {
        const layout = layouts.find(l => l.id === layoutId);
        if (!layout) return;
        setTools(JSON.parse(JSON.stringify(layout.toolsSnapshot)));
        setCurrentStations(JSON.parse(JSON.stringify(layout.stations)));
        setActiveLayoutId(layoutId);
        setSelectedStationId(null);
        setIsMtView(false);
        setSelectedMtSlotId(null);
    }, [layouts, setTools]);

    const saveLayout = useCallback(() => {
        if (!newLayoutName.trim()) return;
        const newLayout: TurretLayout = {
            id: generateId(),
            name: newLayoutName,
            toolsSnapshot: JSON.parse(JSON.stringify(tools)),
            stations: JSON.parse(JSON.stringify(currentStations))
        };
        setLayouts(prev => [...prev, newLayout]);
        setActiveLayoutId(newLayout.id);
        setNewLayoutName('');
    }, [newLayoutName, tools, currentStations, setLayouts]);

    const deleteLayout = useCallback((id: string) => {
        if (layouts.length <= 1) return;
        setLayouts(prev => prev.filter(l => l.id !== id));
        if (activeLayoutId === id) {
            loadLayout(layouts[0].id);
        }
    }, [layouts, activeLayoutId, loadLayout, setLayouts]);

    const updateStationConfig = useCallback((id: number, updates: Partial<StationConfig>) => {
        setCurrentStations(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { 
            ...l, 
            stations: currentStations.map(s => s.id === id ? { ...s, ...updates } : s) 
        } : l));
    }, [activeLayoutId, currentStations, setLayouts]);

    const handleStationClick = useCallback((stationId: number) => {
        const station = currentStations.find(s => s.id === stationId);
        if (station?.type === 'MT') {
            setIsMtView(true);
            setSelectedMtSlotId(1);
        }
        setSelectedStationId(stationId);
    }, [currentStations]);

    const checkCompatibility = useCallback((tool: Tool, station: StationConfig): boolean => {
        if (station.type === 'MT') return tool.stationType === 'MT';
        return tool.toolSize === station.type;
    }, []);

    const handleMountTool = useCallback((tool: Tool, mtIndex?: number) => {
        if (!selectedStationId) return;
        const station = currentStations.find(s => s.id === selectedStationId);
        if (!station || !checkCompatibility(tool, station)) return;

        const updatedTools = tools.map(t => {
            if (t.stationNumber === selectedStationId) {
                if (isMtView) {
                    if (t.mtIndex === mtIndex) return { ...t, stationNumber: 0, mtIndex: 0 };
                } else {
                    return { ...t, stationNumber: 0, mtIndex: 0 };
                }
            }
            if (t.id === tool.id) {
                return { ...t, stationNumber: selectedStationId, mtIndex: mtIndex || 0 };
            }
            return t;
        });
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    }, [selectedStationId, currentStations, checkCompatibility, tools, isMtView, activeLayoutId, setTools, setLayouts]);

    const handleUnmountTool = useCallback((toolId: string) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, stationNumber: 0, mtIndex: 0 } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    }, [tools, activeLayoutId, setTools, setLayouts]);

    const updateToolRotation = useCallback((toolId: string, rotation: number) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, defaultRotation: rotation } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    }, [tools, activeLayoutId, setTools, setLayouts]);

    return {
        activeLayoutId, currentStations, selectedStationId, isMtView, setIsMtView,
        selectedMtSlotId, setSelectedMtSlotId, newLayoutName, setNewLayoutName,
        toolsOnTurret, availableTools,
        loadLayout, saveLayout, deleteLayout, updateStationConfig,
        handleStationClick, handleMountTool, handleUnmountTool, updateToolRotation
    };
};

import { Point, PartGeometry } from '../../types';

/**
 * Квадрат расстояния между точками.
 */
export const distanceSq = (p1: Point, p2: Point) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;

/**
 * Нормализация точки относительно границ (смещение в 0,0).
 */
export const normalize = (p: Point, bbox: PartGeometry['bbox']) => ({
    x: p.x - bbox.minX,
    y: p.y - bbox.minY
});

/**
 * Площадь полигона (метод шнурования).
 */
export const polygonArea = (vertices: Point[]): number => {
    let area = 0;
    for (let i = 0; i < vertices.length; i++) {
        const j = (i + 1) % vertices.length;
        area += vertices[i].x * vertices[j].y;
        area -= vertices[j].x * vertices[i].y;
    }
    return Math.abs(area / 2);
};

/**
 * Геометрический центр набора точек.
 */
export const polygonCenter = (vertices: Point[]): Point => {
    let x = 0;
    let y = 0;
    for(const v of vertices) {
        x += v.x;
        y += v.y;
    }
    return { x: x / vertices.length, y: y / vertices.length };
};

import { Point, PartGeometry } from '../../types';

/**
 * Проверка пересечения луча с сегментом (вспомогательная для Ray Casting).
 */
export const rayIntersectsSegment = (p: Point, a: Point, b: Point): boolean => {
    if ((a.y > p.y) !== (b.y > p.y)) {
        const intersectX = a.x + (p.y - a.y) * (b.x - a.x) / (b.y - a.y);
        if (intersectX > p.x) {
            return true;
        }
    }
    return false;
};

/**
 * Проверка: находится ли точка внутри контура (Ray Casting).
 */
export const isPointInsideContour = (point: Point, partGeometry: PartGeometry): boolean => {
    const { bbox, entities } = partGeometry;
    if (!bbox || !entities) return false;

    if (point.x < bbox.minX || point.x > bbox.maxX || point.y < bbox.minY || point.y > bbox.maxY) {
        return false;
    }

    let intersections = 0;
    for (const entity of entities) {
        switch (entity.type) {
            case 'LWPOLYLINE': {
                const vertices = entity.vertices;
                for (let i = 0; i < vertices.length; i++) {
                    const p1 = vertices[i];
                    const p2 = vertices[(i + 1) % vertices.length];
                    if (!entity.closed && i === vertices.length - 1) continue;
                    if (rayIntersectsSegment(point, p1, p2)) intersections++;
                }
                break;
            }
            case 'LINE': {
                if (rayIntersectsSegment(point, entity.start, entity.end)) intersections++;
                break;
            }
            case 'CIRCLE': {
                const dy = point.y - entity.center.y;
                if (Math.abs(dy) <= entity.radius) {
                    const dx = Math.sqrt(entity.radius * entity.radius - dy * dy);
                    if (entity.center.x - dx > point.x) intersections++;
                    if (entity.center.x + dx > point.x) intersections++;
                }
                break;
            }
            case 'ARC': {
                const dy = point.y - entity.center.y;
                if (Math.abs(dy) <= entity.radius) {
                     const dx = Math.sqrt(entity.radius * entity.radius - dy * dy);
                     const intersectXs = [entity.center.x - dx, entity.center.x + dx];
                     for (const ix of intersectXs) {
                         if (ix > point.x) {
                             const angle = Math.atan2(point.y - entity.center.y, ix - entity.center.x) * (180 / Math.PI);
                             let normAngle = angle < 0 ? angle + 360 : angle;
                             let start = entity.startAngle;
                             let end = entity.endAngle;
                             if (end < start) end += 360;
                             if (normAngle < start) normAngle += 360;
                             if (normAngle >= start && normAngle <= end) intersections++;
                         }
                     }
                }
                break;
            }
        }
    }
    return intersections % 2 !== 0;
};

/**
 * Проверка точки внутри прямоугольника с учетом вращения.
 */
export const isPointInRectangle = (point: Point, rectX: number, rectY: number, width: number, height: number, rotation: number): boolean => {
    const dx = point.x - rectX;
    const dy = point.y - rectY;
    const rad = -rotation * (Math.PI / 180);
    const localX = dx * Math.cos(rad) - dy * Math.sin(rad);
    const localY = dx * Math.sin(rad) + dy * Math.cos(rad);
    return localX >= 0 && localX <= width && localY >= 0 && localY <= height;
};

import { Point, Part, Tool, ToolShape } from '../../types';

/**
 * Расчет физических границ детали при повороте.
 */
export const getRotatedExtents = (part: Part, rotation: number, tools: Tool[]) => {
    const rad = (rotation * Math.PI) / 180;
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);

    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;

    const basePoints: Point[] = [
        { x: 0, y: 0 },
        { x: part.geometry.width, y: 0 },
        { x: part.geometry.width, y: part.geometry.height },
        { x: 0, y: part.geometry.height }
    ];

    basePoints.forEach(p => {
        const rx = p.x * cos - p.y * sin;
        const ry = p.x * sin + p.y * cos;
        if (rx < minX) minX = rx; if (rx > maxX) maxX = rx;
        if (ry < minY) minY = ry; if (ry > maxY) maxY = ry;
    });

    part.punches.forEach(p => {
        const tool = tools.find(t => t.id === p.toolId);
        if (!tool) return;
        const punchRad = (p.rotation + rotation) * Math.PI / 180;
        const tCos = Math.abs(Math.cos(punchRad));
        const tSin = Math.abs(Math.sin(punchRad));
        let tW = tool.width;
        let tH = tool.shape === ToolShape.Circle ? tool.width : tool.height;
        const effW = tW * tCos + tH * tSin;
        const effH = tW * tSin + tH * tCos;
        const rx = p.x * cos - p.y * sin;
        const ry = p.x * sin + p.y * cos;
        if (rx - effW/2 < minX) minX = rx - effW/2;
        if (rx + effW/2 > maxX) maxX = rx + effW/2;
        if (ry - effH/2 < minY) minY = ry - effH/2;
        if (ry + effH/2 > maxY) maxY = ry + effH/2;
    });

    return {
        width: maxX - minX,
        height: maxY - minY,
        ox: -minX,
        oy: -minY
    };
};

/**
 * Вершины повернутого прямоугольника.
 */
export const getRotatedRectVertices = (x: number, y: number, w: number, h: number, rotation: number): Point[] => {
    const rad = rotation * (Math.PI / 180);
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);
    return [
        { x: x, y: y },
        { x: x + w * cos, y: y + w * sin },
        { x: x + w * cos - h * sin, y: y + w * sin + h * cos },
        { x: x - h * sin, y: y + h * cos }
    ];
};

/**
 * Координаты углов инструмента с учетом вращения.
 */
export const getToolCorners = (tool: Tool, x: number, y: number, rotation: number): Point[] => {
    const w = tool.width;
    const h = tool.shape === ToolShape.Circle ? tool.width : tool.height;
    const rad = rotation * (Math.PI / 180);
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);
    const corners = [{ x: -w/2, y: -h/2 }, { x: w/2, y: -h/2 }, { x: w/2, y: h/2 }, { x: -w/2, y: h/2 }];
    return corners.map(p => ({
        x: x + (p.x * cos - p.y * sin),
        y: y + (p.x * sin + p.y * cos)
    }));
};

import { Point, DxfEntity } from '../../types';

export const segmentIntersectsCircle = (p1: Point, p2: Point, center: Point, r: number): boolean => {
    const d1Sq = (p1.x - center.x)**2 + (p1.y - center.y)**2;
    const d2Sq = (p2.x - center.x)**2 + (p2.y - center.y)**2;
    const r2 = r * r;
    if (d1Sq < r2 || d2Sq < r2) return true;
    const lx = p2.x - p1.x;
    const ly = p2.y - p1.y;
    const lenSq = lx * lx + ly * ly;
    if (lenSq === 0) return false;
    const dot = ((center.x - p1.x) * lx + (center.y - p1.y) * ly) / lenSq;
    const closestX = p1.x + dot * lx;
    const closestY = p1.y + dot * ly;
    if (dot < 0 || dot > 1) return false;
    const distSq = (closestX - center.x)**2 + (closestY - center.y)**2;
    return distSq < (r2 - 0.0001); 
};

export const segmentIntersectsArc = (p1: Point, p2: Point, center: Point, r: number, startAngle: number, endAngle: number): boolean => {
    if (!segmentIntersectsCircle(p1, p2, center, r)) return false;
    const dx = p1.x - center.x; const dy = p1.y - center.y;
    const vx = p2.x - p1.x; const vy = p2.y - p1.y;
    const A = vx*vx + vy*vy;
    const B = 2 * (dx*vx + dy*vy);
    const C = (dx*dx + dy*dy) - (r*r);
    const det = B*B - 4*A*C;
    if (det < 0) return false;
    const sqrtDet = Math.sqrt(det);
    const ts = [(-B - sqrtDet) / (2*A), (-B + sqrtDet) / (2*A)];
    for (const t of ts) {
        if (t >= 0 && t <= 1) {
            const ix = p1.x + t * vx;
            const iy = p1.y + t * vy;
            const angle = Math.atan2(iy - center.y, ix - center.x) * (180 / Math.PI);
            let normAngle = angle < 0 ? angle + 360 : angle;
            let s = startAngle; let e = endAngle;
            if (e < s) e += 360;
            if (normAngle < s) normAngle += 360;
            if (normAngle >= s && normAngle <= e) return true;
        }
    }
    return false;
};

export const segmentIntersectsGeometry = (p1: Point, p2: Point, entities: DxfEntity[]): boolean => {
    const minX = Math.min(p1.x, p2.x) - 0.1; const maxX = Math.max(p1.x, p2.x) + 0.1;
    const minY = Math.min(p1.y, p2.y) - 0.1; const maxY = Math.max(p1.y, p2.y) + 0.1;
    const checkLine = (a: Point, b: Point) => {
        const denominator = ((p2.x - p1.x) * (b.y - a.y)) - ((p2.y - p1.y) * (b.x - a.x));
        if (denominator === 0) return false;
        const r = (((p1.y - a.y) * (b.x - a.x)) - ((p1.x - a.x) * (b.y - a.y))) / denominator;
        const s = (((p1.y - a.y) * (p2.x - p1.x)) - ((p1.x - a.x) * (p2.y - p1.y))) / denominator;
        return (r > 0.01 && r < 0.99) && (s > 0.01 && s < 0.99);
    };
    for (const entity of entities) {
        if (entity.type === 'LINE') {
            if (checkLine(entity.start, entity.end)) return true;
        } else if (entity.type === 'LWPOLYLINE') {
            const v = entity.vertices;
            for (let i = 0; i < v.length - 1; i++) if (checkLine(v[i], v[i+1])) return true;
            if (entity.closed && v.length > 1) if (checkLine(v[v.length-1], v[0])) return true;
        } else if (entity.type === 'ARC') {
            if (entity.center.x + entity.radius < minX || entity.center.x - entity.radius > maxX || 
                entity.center.y + entity.radius < minY || entity.center.y - entity.radius > maxY) continue;
            if (segmentIntersectsArc(p1, p2, entity.center, entity.radius, entity.startAngle, entity.endAngle)) return true;
        } else if (entity.type === 'CIRCLE') {
            if (entity.center.x + entity.radius < minX || entity.center.x - entity.radius > maxX || 
                entity.center.y + entity.radius < minY || entity.center.y - entity.radius > maxY) continue;
            if (segmentIntersectsCircle(p1, p2, entity.center, entity.radius)) return true;
        }
    }
    return false;
};

import { Point, Part, PartGeometry, PartProfile, Tool, ToolShape } from '../../types';
import { distanceSq, polygonArea, polygonCenter, normalize } from './math';
import { segmentIntersectsGeometry } from './intersections';

export type Segment = { 
    p1: Point; p2: Point; type: 'line' | 'arc'; radius?: number; center?: Point; originalEntity?: any; 
};

export type ProcessedGeometry = { 
    vertices: Point[], segments: Segment[], bbox: PartGeometry['bbox'], holeCenters: { point: Point, rotation?: number }[],
};

export const findClosedLoops = (segments: Segment[]): { vertices: Point[], segmentIndices: number[] }[] => {
    const adj = new Map<string, number[]>();
    const getKey = (p: Point) => `${p.x.toFixed(3)},${p.y.toFixed(3)}`;
    segments.forEach((s, i) => {
        [getKey(s.p1), getKey(s.p2)].forEach(k => {
            if (!adj.has(k)) adj.set(k, []);
            adj.get(k)!.push(i);
        });
    });
    const visitedSegs = new Set<number>();
    const loops: { vertices: Point[], segmentIndices: number[] }[] = [];
    segments.forEach((seg, startIdx) => {
        if (visitedSegs.has(startIdx)) return;
        const componentSegs = new Set<number>();
        const q = [startIdx]; visitedSegs.add(startIdx); componentSegs.add(startIdx);
        while(q.length > 0) {
            const currIdx = q.pop()!; const s = segments[currIdx];
            [getKey(s.p1), getKey(s.p2)].forEach(k => {
                (adj.get(k) || []).forEach(nIdx => {
                    if (!visitedSegs.has(nIdx)) { visitedSegs.add(nIdx); componentSegs.add(nIdx); q.push(nIdx); }
                });
            });
        }
        const uniquePoints = new Map<string, Point>();
        const pointDegrees = new Map<string, number>();
        componentSegs.forEach(idx => {
            const s = segments[idx];
            [s.p1, s.p2].forEach(p => {
                const k = getKey(p);
                uniquePoints.set(k, p);
                pointDegrees.set(k, (pointDegrees.get(k) || 0) + 1);
            });
        });
        let isClosed = true;
        for(const deg of pointDegrees.values()) if (deg % 2 !== 0) { isClosed = false; break; }
        if (isClosed && uniquePoints.size > 2) {
            loops.push({ vertices: Array.from(uniquePoints.values()), segmentIndices: Array.from(componentSegs) });
        }
    });
    return loops;
};

export const getOuterLoopIndices = (segments: Segment[]): Set<number> => {
    const loops = findClosedLoops(segments);
    let maxArea = -1; let indices: number[] = [];
    loops.forEach(l => {
        const area = polygonArea(l.vertices);
        if(area > maxArea) { maxArea = area; indices = l.segmentIndices; }
    });
    return new Set(indices);
};

export const getGeometryFromEntities = (part: Part): ProcessedGeometry | null => {
    const { entities, bbox } = part.geometry;
    if (!entities || !bbox) return null;
    const vertices: Point[] = []; const segments: Segment[] = [];
    entities.forEach(entity => {
        switch(entity.type) {
            case 'LINE': {
                const p1 = normalize(entity.start, bbox); const p2 = normalize(entity.end, bbox);
                vertices.push(p1, p2); segments.push({ p1, p2, type: 'line', originalEntity: entity });
                break;
            }
            case 'LWPOLYLINE': {
                if (entity.vertices.length < 2) break;
                const points = entity.vertices.map(v => normalize(v, bbox));
                for(let i = 0; i < points.length - 1; i++) {
                    vertices.push(points[i]); segments.push({ p1: points[i], p2: points[i+1], type: 'line', originalEntity: entity });
                }
                vertices.push(points[points.length-1]);
                if (entity.closed) segments.push({ p1: points[points.length-1], p2: points[0], type: 'line', originalEntity: entity });
                break;
            }
            case 'ARC': {
                const d2r = Math.PI / 180; const startRad = entity.startAngle * d2r; const endRad = entity.endAngle * d2r;
                const p1 = normalize({ x: entity.center.x + entity.radius * Math.cos(startRad), y: entity.center.y + entity.radius * Math.sin(startRad) }, bbox);
                const p2 = normalize({ x: entity.center.x + entity.radius * Math.cos(endRad), y: entity.center.y + entity.radius * Math.sin(endRad) }, bbox);
                const center = normalize(entity.center, bbox);
                vertices.push(p1, p2); segments.push({ p1, p2, type: 'arc', radius: entity.radius, center, originalEntity: entity });
                break;
            }
            case 'CIRCLE': {
                const r = entity.radius; const c = entity.center; const center = normalize(c, bbox);
                const points = [{x: c.x + r, y: c.y}, {x: c.x, y: c.y + r}, {x: c.x - r, y: c.y}, {x: c.x, y: c.y - r}].map(p => normalize(p, bbox));
                vertices.push(...points);
                for (let i = 0; i < points.length; i++) segments.push({p1: points[i], p2: points[(i+1) % 4], type: 'arc', radius: r, center, originalEntity: entity });
                break;
            }
        }
    });
    const shapeCenters: { point: Point, rotation?: number }[] = [];
    entities.forEach(e => { if (e.type === 'CIRCLE') shapeCenters.push({ point: normalize(e.center, bbox), rotation: 0 }); });
    const detectedLoops = findClosedLoops(segments);
    let maxArea = -1; let mainLoopIndex = -1;
    detectedLoops.forEach((loop, idx) => {
        const area = polygonArea(loop.vertices);
        if (area > maxArea) { maxArea = area; mainLoopIndex = idx; }
    });
    detectedLoops.forEach((loop, idx) => {
        if (idx !== mainLoopIndex) {
            let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
            loop.vertices.forEach(v => {
                if (v.x < minX) minX = v.x; if (v.x > maxX) maxX = v.x;
                if (v.y < minY) minY = v.y; if (v.y > maxY) maxY = v.y;
            });
            shapeCenters.push({ point: polygonCenter(loop.vertices), rotation: (maxY - minY) > (maxX - minX) ? 90 : 0 });
        }
    });
    return { vertices, segments, bbox, holeCenters: shapeCenters };
};

export const detectPartProfile = (geometry: PartGeometry): PartProfile => {
    const { bbox, entities, height } = geometry;
    const width = bbox.maxX - bbox.minX;
    if (entities.length === 0) return { type: 'flat', orientation: 'vertical', dims: { a: width, b: 0, c: 0 } };
    const toSvgY = (rawY: number) => rawY - bbox.minY; const toSvgX = (rawX: number) => rawX - bbox.minX;
    const verticalBendCandidates: number[] = []; const horizontalBendCandidates: number[] = [];
    const checkPoint = (rawP: Point) => {
        const sx = toSvgX(rawP.x); const sy = toSvgY(rawP.y);
        if (sy > (height - 50) && sy < (height - 0.5)) verticalBendCandidates.push(sx);
        if (sy > 0.5 && sy < 50) verticalBendCandidates.push(sx);
        if (sx > 0.5 && sx < 50) horizontalBendCandidates.push(sy);
        if (sx > (width - 50) && sx < (width - 0.5)) horizontalBendCandidates.push(sy);
    };
    entities.forEach(e => {
        if (e.type === 'ARC') checkPoint(e.center);
        else if (e.type === 'LWPOLYLINE') e.vertices.forEach(v => checkPoint(v));
    });
    const cluster = (coords: number[], rangeMax: number) => {
        if (coords.length === 0) return [];
        coords.sort((a, b) => a - b);
        const res: number[] = []; let cur: number[] = [coords[0]];
        for (let i = 1; i < coords.length; i++) {
            if (coords[i] - coords[i-1] < 20) cur.push(coords[i]);
            else { res.push(cur.reduce((a,b)=>a+b,0)/cur.length); cur = [coords[i]]; }
        }
        res.push(cur.reduce((a,b)=>a+b,0)/cur.length);
        return res.filter(v => v > 50 && v < (rangeMax - 50));
    };
    const vLines = cluster(verticalBendCandidates, width);
    if (vLines.length === 1) return { type: 'L', orientation: 'vertical', dims: { a: vLines[0], b: width - vLines[0], c: 0 } };
    if (vLines.length === 2) return { type: 'U', orientation: 'vertical', dims: { a: vLines[0], b: vLines[1] - vLines[0], c: width - vLines[1] } };
    const hLines = cluster(horizontalBendCandidates, height);
    if (hLines.length === 1) return { type: 'L', orientation: 'horizontal', dims: { a: hLines[0], b: height - hLines[0], c: 0 } };
    if (hLines.length === 2) return { type: 'U', orientation: 'horizontal', dims: { a: hLines[0], b: hLines[1] - hLines[0], c: height - hLines[1] } };
    return { type: 'flat', orientation: 'vertical', dims: { a: width, b: 0, c: 0 } };
};

export const calculatePartPhysicalExtents = (part: Part, tools: Tool[]): { width: number, height: number, offsetX: number, offsetY: number } => {
    let minX = 0; let minY = 0; let maxX = part.geometry.width; let maxY = part.geometry.height;
    part.punches.forEach(p => {
        const tool = tools.find(t => t.id === p.toolId); if (!tool) return;
        const rad = p.rotation * Math.PI / 180;
        const tW = tool.width; const tH = tool.shape === ToolShape.Circle ? tool.width : tool.height;
        const effW = tW * Math.abs(Math.cos(rad)) + tH * Math.abs(Math.sin(rad));
        const effH = tW * Math.abs(Math.sin(rad)) + tH * Math.abs(Math.cos(rad));
        minX = Math.min(minX, p.x - effW/2); maxX = Math.max(maxX, p.x + effW/2);
        minY = Math.min(minY, p.y - effH/2); maxY = Math.max(maxY, p.y + effH/2);
    });
    return { width: maxX - minX, height: maxY - minY, offsetX: -minX, offsetY: -minY };
};

import { Point, Part, PlacedPart, SnapMode } from '../../types';
import { distanceSq } from './math';
import { isPointInsideContour } from './predicates';
import { getRotatedRectVertices } from './transform';
import { getGeometryFromEntities } from './topology';

export const doPartsIntersect = (partA: Part, posA: Point, rotA: number, partB: Part, posB: Point, rotB: number, margin: number = 0): boolean => {
    const getSegs = (p: Part, pos: Point, rot: number) => {
        const rad = rot * Math.PI / 180; const c = Math.cos(rad); const s = Math.sin(rad);
        const processed = getGeometryFromEntities(p);
        return (processed?.segments || []).map(seg => {
            const tr = (pt: Point) => ({ x: pos.x + (pt.x * c - pt.y * s), y: pos.y + (pt.x * s + pt.y * c) });
            return { p1: tr(seg.p1), p2: tr(seg.p2) };
        });
    };
    const segsA = getSegs(partA, posA, rotA); const segsB = getSegs(partB, posB, rotB);
    const intersect = (p1: Point, p2: Point, p3: Point, p4: Point) => {
        const det = (p2.x - p1.x) * (p4.y - p3.y) - (p2.y - p1.y) * (p4.x - p3.x);
        if (det === 0) return false;
        const lambda = ((p4.y - p3.y) * (p4.x - p1.x) + (p3.x - p4.x) * (p4.y - p1.y)) / det;
        const gamma = ((p1.y - p2.y) * (p4.x - p1.x) + (p2.x - p1.x) * (p4.y - p1.y)) / det;
        return (0 < lambda && lambda < 1) && (0 < gamma && gamma < 1);
    };
    for (const sA of segsA) for (const sB of segsB) if (intersect(sA.p1, sA.p2, sB.p1, sB.p2)) return true;
    const checkIn = (pts: Point[], target: Part, tPos: Point, tRot: number) => {
        const rad = -tRot * Math.PI / 180; const c = Math.cos(rad); const s = Math.sin(rad);
        for (const pt of pts) {
            const dx = pt.x - tPos.x; const dy = pt.y - tPos.y;
            if (isPointInsideContour({ x: dx * c - dy * s, y: dx * s + dy * c }, target.geometry)) return true;
        }
        return false;
    };
    if (checkIn(segsA.map(s => s.p1), partB, posB, rotB)) return true;
    if (checkIn(segsB.map(s => s.p1), partA, posA, rotA)) return true;
    return false;
};

export const calculateNestingSnap = (draggedPart: PlacedPart, placedParts: PlacedPart[], allParts: Part[], snapDistance: number = 10): { x: number, y: number } | null => {
    const partDef = allParts.find(p => p.id === draggedPart.partId); if (!partDef) return null;
    const dragVertices = getRotatedRectVertices(draggedPart.x, draggedPart.y, partDef.geometry.width, partDef.geometry.height, draggedPart.rotation);
    let bestSnap: { x: number, y: number, distSq: number } | null = null;
    const snapDistSq = snapDistance * snapDistance;
    for (const target of placedParts) {
        if (target.id === draggedPart.id) continue;
        const targetDef = allParts.find(p => p.id === target.partId); if (!targetDef) continue;
        const targetVertices = getRotatedRectVertices(target.x, target.y, targetDef.geometry.width, targetDef.geometry.height, target.rotation);
        for (const dv of dragVertices) for (const tv of targetVertices) {
            const d2 = distanceSq(dv, tv);
            if (d2 < snapDistSq && (!bestSnap || d2 < bestSnap.distSq)) {
                bestSnap = { x: draggedPart.x + (tv.x - dv.x), y: draggedPart.y + (tv.y - dv.y), distSq: d2 };
            }
        }
    }
    return bestSnap ? { x: bestSnap.x, y: bestSnap.y } : null;
};

import { Point, SnapMode } from '../../types';
import { distanceSq } from './math';
import { ProcessedGeometry, Segment } from './topology';

export type SnapTarget = 'start' | 'end' | 'middle';
export interface SnapResult {
    point: Point; angle: number; snapTarget: SnapTarget; wasNormalized: boolean; forceRotation?: number;
}

const distanceToSegmentSq = (p: Point, seg: Segment) => {
    const { p1, p2 } = seg;
    if (seg.type === 'arc' && seg.center && seg.radius) {
         const distToCenter = Math.sqrt(distanceSq(p, seg.center));
         const distToCurve = Math.abs(distToCenter - seg.radius);
         const l2 = distanceSq(p1, p2);
         if (l2 === 0) return distanceSq(p, p1);
         let t = ((p.x - p1.x) * (p2.x - p1.x) + (p.y - p1.y) * (p2.y - p1.y)) / l2;
         if (t >= 0 && t <= 1) return distToCurve * distToCurve;
         return Math.min(distanceSq(p, p1), distanceSq(p, p2));
    }
    const l2 = distanceSq(p1, p2);
    if (l2 === 0) return distanceSq(p, p1);
    let t = Math.max(0, Math.min(1, ((p.x - p1.x) * (p2.x - p1.x) + (p.y - p1.y) * (p2.y - p1.y)) / l2));
    return distanceSq(p, { x: p1.x + t * (p2.x - p1.x), y: p1.y + t * (p2.y - p1.y) });
};

export const findClosestSegment = (point: Point, geometry: ProcessedGeometry | null, threshold: number = 100): { p1: Point, p2: Point, angle: number, wasNormalized: boolean } | null => {
    if (!geometry) return null;
    let closest: any = null;
    let minDst = (threshold * Math.max(0.1, (geometry.bbox.maxX - geometry.bbox.minX) / 500))**2;
    geometry.segments.forEach(seg => {
        const d2 = distanceToSegmentSq(point, seg);
        if (d2 < minDst) {
            minDst = d2;
            closest = { p1: seg.p1, p2: seg.p2, angle: Math.atan2(seg.p2.y - seg.p1.y, seg.p2.x - seg.p1.x) * 180 / Math.PI, wasNormalized: false };
        }
    });
    return closest;
};

export const findSnapPoint = (mousePoint: Point, processedGeometry: ProcessedGeometry | null, mode: SnapMode): SnapResult | null => {
    if (mode === SnapMode.Off || !processedGeometry) return null;
    const { vertices, segments, holeCenters, bbox } = processedGeometry;
    if (mode === SnapMode.ShapeCenter && holeCenters.length > 0) {
        let best: any = null; let minD = Infinity;
        holeCenters.forEach(c => { const d = distanceSq(mousePoint, c.point); if (d < minD) { minD = d; best = c; } });
        return best ? { point: best.point, angle: 0, snapTarget: 'middle', wasNormalized: false, forceRotation: best.rotation } : null;
    }
    if (vertices.length === 0) return null;
    let bestRes: SnapResult | null = null; let minD = (25 * Math.max(0.1, (bbox.maxX - bbox.minX) / 500))**2;
    if (mode === SnapMode.Vertex) {
        let cv: Point | null = null; let mvD = Infinity;
        vertices.forEach(v => { const d = distanceSq(mousePoint, v); if (d < mvD) { mvD = d; cv = v; } });
        if (cv && mvD < minD) {
            const connected = segments.filter(s => distanceSq(s.p1, cv!) < 1e-9 || distanceSq(s.p2, cv!) < 1e-9);
            const s = connected[0] || segments[0];
            const ang = Math.atan2(s.p2.y - s.p1.y, s.p2.x - s.p1.x) * 180 / Math.PI;
            return { point: cv, angle: ang, snapTarget: distanceSq(cv, s.p1) < 1e-9 ? 'start' : 'end', wasNormalized: false };
        }
    }
    if (mode === SnapMode.SegmentCenter) {
        segments.forEach(s => {
            const cp = { x: (s.p1.x + s.p2.x)/2, y: (s.p1.y + s.p2.y)/2 }; const d = distanceSq(mousePoint, cp);
            if (d < minD) { minD = d; bestRes = { point: cp, angle: Math.atan2(s.p2.y - s.p1.y, s.p2.x - s.p1.x) * 180 / Math.PI, snapTarget: 'middle', wasNormalized: false }; }
        });
    }
    return bestRes;
};

