import { generateNibblePunches } from '../punchingGenerators';

export const processLineSegment = (
    seg: Segment, 
    geometry: PartGeometry,
    tools: Tool[], 
    settings: AutoPunchSettings,
    punches: Omit<PlacedTool, 'id'>[],
    allSegments: Segment[],
    neighbors: { start: Segment | undefined, end: Segment | undefined },
    jointVertices: Set<string>
) => {
    const dx = seg.p2.x - seg.p1.x;
    const dy = seg.p2.y - seg.p1.y;
    const len = Math.sqrt(dx*dx + dy*dy);
    const { bbox } = geometry;

    const isExtreme = (p: Point) => Math.abs(p.x - bbox.minX) < TOLERANCE.GEO || Math.abs(p.x - bbox.maxX) < TOLERANCE.GEO || 
                                  Math.abs(p.y - bbox.minY) < TOLERANCE.GEO || Math.abs(p.y - bbox.maxY) < TOLERANCE.GEO;

    const getExtRange = (vertex: Point, dir: {x: number, y: number}, neighbor: Segment | undefined) => {
        if (jointVertices.has(getPointKey(vertex))) return { min: -settings.microJointLength, max: -settings.microJointLength };
        if (neighbor && neighbor.type === 'arc') return { min: settings.extension, max: settings.extension };
        const probe = { x: vertex.x + dir.x * 0.1, y: vertex.y + dir.y * 0.1 };
        if (isPointInsideContour(probe, geometry)) return { min: 0, max: 0 };
        return isExtreme(vertex) ? { min: settings.extension, max: settings.extension } : { min: settings.extension, max: Math.max(settings.extension, settings.vertexTolerance) };
    };

    const ux = dx/len; const uy = dy/len;
    const startRange = getExtRange(seg.p1, { x: -ux, y: -uy }, neighbors.start);
    const endRange = getExtRange(seg.p2, { x: ux, y: uy }, neighbors.end);
    const minReqLen = len + startRange.min + endRange.min;
    const maxAllowedLen = len + startRange.max + endRange.max;

    const singleHitCandidates = tools.filter(t => [ToolShape.Rectangle, ToolShape.Square, ToolShape.Oblong].includes(t.shape) && t.width >= (minReqLen - 0.01) && t.width <= (maxAllowedLen + 0.01));

    let tool: Tool | undefined;
    let isSingleHit = false;

    if (singleHitCandidates.length > 0) {
        singleHitCandidates.sort((a, b) => {
            const s = (t: Tool) => t.shape === ToolShape.Rectangle ? 10 : t.shape === ToolShape.Square ? 5 : 0;
            return s(b) - s(a) || a.width - b.width;
        });
        tool = singleHitCandidates[0];
        isSingleHit = true;
    } else {
        const candidates = getPreferredTools('line', len, 0, tools);
        if (candidates.length > 0) tool = candidates[0];
    }

    if (!tool) return;

    const angle = Math.atan2(dy, dx) * 180 / Math.PI;
    const perpOffset = (tool.shape === ToolShape.Circle ? tool.width : tool.height) / 2;
    const mid = { x: (seg.p1.x + seg.p2.x)/2, y: (seg.p1.y + seg.p2.y)/2 };
    const sign = isPointInsideContour({ x: mid.x - uy * perpOffset * 1.1, y: mid.y + ux * perpOffset * 1.1 }, geometry) ? -1 : 1;

    let aStartExt = startRange.min;
    if (isSingleHit) aStartExt = (settings.extension >= Math.max(startRange.min, tool.width - len - endRange.max) && settings.extension <= Math.min(startRange.max, tool.width - len - endRange.min)) ? settings.extension : Math.max(startRange.min, tool.width - len - endRange.max);
    const aEndExt = isSingleHit ? (tool.width - len - aStartExt) : endRange.min;

    const segmentPunches = generateNibblePunches(seg.p1, seg.p2, tool, { extensionStart: aStartExt, extensionEnd: aEndExt, minOverlap: settings.overlap, hitPointMode: 'offset', toolPosition: 'long' }, angle, false, angle, perpOffset * sign);

    segmentPunches.forEach((p, idx) => {
        let curX = p.x, curY = p.y;
        if (isToolGouging(tool!, curX, curY, p.rotation, geometry, geometry.bbox, seg, allSegments)) {
            if (idx === 0 && aStartExt > 0) {
                if (!isToolGouging(tool!, curX + ux * aStartExt, curY + uy * aStartExt, p.rotation, geometry, geometry.bbox, seg, allSegments)) { curX += ux * aStartExt; curY += uy * aStartExt; }
            } else if (idx === segmentPunches.length - 1 && aEndExt > 0) {
                if (!isToolGouging(tool!, curX - ux * aEndExt, curY - uy * aEndExt, p.rotation, geometry, geometry.bbox, seg, allSegments)) { curX -= ux * aEndExt; curY -= uy * aEndExt; }
            }
        }
        if (!isToolGouging(tool!, curX, curY, p.rotation, geometry, geometry.bbox, seg, allSegments)) punches.push({ ...p, x: curX, y: curY });
    });
};

/**
 * ОТВЕТСТВЕННОСТЬ: Генерация ударов для ARC сегментов.
 */
import { Tool, PlacedTool, ToolShape, PartGeometry, AutoPunchSettings } from '../../types';
import { isPointInsideContour, Segment, isToolGouging } from '../geometry';
import { denormalizePoint, calculateScallopStep, getHitKey, getPointKey } from '../punchingUtils';
import { getPreferredTools } from '../punchingTools';

export const processArcSegment = (
    seg: Segment,
    geometry: PartGeometry,
    tools: Tool[],
    settings: AutoPunchSettings,
    jointVertices: Set<string>,
    punches: Omit<PlacedTool, 'id'>[],
    placedSingleHits: Set<string>,
    allSegments: Segment[]
) => {
    const r = seg.radius || 0;
    const center = seg.center || {x:0,y:0};
    if (r <= 0) return;

    const ang1 = Math.atan2(seg.p1.y - center.y, seg.p1.x - center.x);
    let ang2 = Math.atan2(seg.p2.y - center.y, seg.p2.x - center.x);
    let diff = ang2 - ang1;
    if (diff < -Math.PI) diff += 2 * Math.PI;
    if (diff > Math.PI) diff -= 2 * Math.PI;

    const isProbeInMaterial = isPointInsideContour(denormalizePoint({ x: center.x + (r + 0.1) * Math.cos(ang1 + diff / 2), y: center.y + (r + 0.1) * Math.sin(ang1 + diff / 2) }, geometry.bbox), geometry);

    const exactTools = getPreferredTools('circle', r * 2, 0, tools, settings.toleranceRound);
    if (exactTools.length > 0 && Math.abs(exactTools[0].width - r * 2) <= settings.toleranceRound) {
        const k = getHitKey(center.x, center.y);
        if (!placedSingleHits.has(k)) { punches.push({ toolId: exactTools[0].id, x: center.x, y: center.y, rotation: 0 }); placedSingleHits.add(k); }
        return; 
    }

    let nibbleCandidates = tools.filter(t => t.shape === ToolShape.Circle && (!isProbeInMaterial || (t.width / 2) < (r - 0.1))).sort((a,b) => b.width - a.width);
    if (nibbleCandidates.length === 0) return; 

    const tool = nibbleCandidates[0];
    const punchR = isProbeInMaterial ? (r - tool.width/2) : (r + tool.width/2);
    if (punchR <= 0) return; 

    let aDiff = Math.abs(diff);
    let aAng1 = ang1;
    const isClosed = Math.abs(diff) > (2 * Math.PI - 0.01);

    if (!isClosed) {
        const mStart = jointVertices.has(getPointKey(seg.p1)) ? (settings.microJointLength / r) : (settings.vertexTolerance / r);
        const mEnd = jointVertices.has(getPointKey(seg.p2)) ? (settings.microJointLength / r) : (settings.vertexTolerance / r);
        if (aDiff <= (mStart + mEnd)) return;
        aAng1 += (diff > 0 ? 1 : -1) * mStart;
        aDiff -= (mStart + mEnd);
    }

    const step = calculateScallopStep(tool.width/2, settings.scallopHeight) / punchR;
    const steps = Math.ceil(aDiff / step);
    const rStep = (diff > 0 ? aDiff : -aDiff) / steps;

    for(let i=0; i <= (isClosed ? steps - 1 : steps); i++) {
        const a = aAng1 + i * rStep;
        let px = center.x + punchR * Math.cos(a), py = center.y + punchR * Math.sin(a);
        if (!isToolGouging(tool, px, py, 0, geometry, geometry.bbox, seg, allSegments)) punches.push({ toolId: tool.id, x: px, y: py, rotation: 0 });
    }
};

/**
 * ОТВЕТСТВЕННОСТЬ: Оркестрация процесса автоматической расстановки инструмента по контуру.
 */
import { Part, Tool, AutoPunchSettings, TurretLayout, TeachCycle, PlacedTool, Point } from '../../types';
import { getGeometryFromEntities, getOuterLoopIndices } from '../geometry';
import { findTeachCycleMatches } from '../teachLogic';
import { TOLERANCE, getPointKey } from '../punchingUtils';
import { generateId } from '../../utils/helpers';
import { detectAndPunchShapes, detectLoopTools } from '../punchingGenerators';
import { getVectorFromVertex } from './contourUtils';
import { processLineSegment } from './contourLineHandler';
import { processArcSegment } from './contourArcHandler';

export const generateContourPunches = (
    geometry: any, // PartGeometry
    tools: Tool[],
    settings: AutoPunchSettings,
    turretLayouts: TurretLayout[],
    teachCycles: TeachCycle[]
): Omit<PlacedTool, 'id'>[] => {
    const processed = getGeometryFromEntities({ geometry } as Part); 
    if (!processed) return [];

    const punches: Omit<PlacedTool, 'id'>[] = [];
    const coveredIndices = new Set<number>();
    const placedSingleHits = new Set<string>();
    const vertexMap = new Map<string, { point: Point, segmentIndices: number[] }>();

    processed.segments.forEach((seg, idx) => {
        [seg.p1, seg.p2].forEach(p => {
            const k = getPointKey(p);
            if (!vertexMap.has(k)) vertexMap.set(k, { point: p, segmentIndices: [] });
            vertexMap.get(k)!.segmentIndices.push(idx);
        });
    });

    const jointVertices = new Set<string>();
    if (settings.microJointsEnabled) {
        const outerIndices = getOuterLoopIndices(processed.segments);
        const { minX, minY, maxX, maxY } = processed.bbox;
        const cornerTargets = [{ x: minX, y: maxY }, { x: maxX, y: maxY }, { x: maxX, y: minY }, { x: minX, y: minY }];

        cornerTargets.forEach(target => {
            let bestScore = -Infinity, bestKey = null;
            vertexMap.forEach((data, key) => {
                let angleBonus = 0;
                if (data.segmentIndices.length === 2) {
                    const v1 = getVectorFromVertex(processed.segments[data.segmentIndices[0]], data.point);
                    const v2 = getVectorFromVertex(processed.segments[data.segmentIndices[1]], data.point);
                    const dot = v1.x * v2.x + v1.y * v2.y;
                    const ang = Math.acos(Math.max(-1, Math.min(1, dot / (Math.sqrt(v1.x**2+v1.y**2) * Math.sqrt(v2.x**2+v2.y**2))))) * 180 / Math.PI;
                    if (Math.abs(ang - 90) < 5) angleBonus = 1000;
                }
                const score = angleBonus - Math.sqrt((data.point.x - target.x)**2 + (data.point.y - target.y)**2) * 0.5;
                if (score > bestScore) { bestScore = score; bestKey = key; }
            });
            if (bestKey) jointVertices.add(bestKey);
        });
    }

    if (settings.useTeachCycles && teachCycles.length > 0) {
        const matches = findTeachCycleMatches(processed, teachCycles);
        matches.matches.forEach(p => punches.push(p));
        matches.coveredSegmentIndices.forEach(i => coveredIndices.add(i));
    }

    let availableTools = tools;
    if (settings.toolSourceType === 'turret' && settings.turretLayoutId) {
        const layout = turretLayouts.find(l => l.id === settings.turretLayoutId);
        if (layout) availableTools = layout.toolsSnapshot.filter(t => !!t.stationNumber);
    }

    punches.push(...detectAndPunchShapes(geometry, processed, availableTools, settings, coveredIndices));
    punches.push(...detectLoopTools(processed, availableTools, settings, coveredIndices));

    processed.segments.forEach((seg, idx) => {
        if (coveredIndices.has(idx)) return;
        if (seg.type === 'line') {
            const n1 = vertexMap.get(getPointKey(seg.p1))?.segmentIndices.find(i => i !== idx);
            const n2 = vertexMap.get(getPointKey(seg.p2))?.segmentIndices.find(i => i !== idx);
            processLineSegment(seg, geometry, availableTools, settings, punches, processed.segments, { start: n1 !== undefined ? processed.segments[n1] : undefined, end: n2 !== undefined ? processed.segments[n2] : undefined }, jointVertices);
        } else if (seg.type === 'arc') {
            processArcSegment(seg, geometry, availableTools, settings, jointVertices, punches, placedSingleHits, processed.segments);
        }
    });

    return punches;
};

