/**
 * ОТВЕТСТВЕННОСТЬ: Расчет позиции и угла одного удара с учетом Snap и геометрии.
 */
import { useCallback } from 'react';
import { Part, Tool, Point, SnapMode, PlacementSide, PlacedTool } from '../../types';
import { ProcessedGeometry, findSnapPoint, isPointInsideContour } from '../../services/geometry';
import { calculateEdgePlacement } from '../../services/placement';

interface SinglePunchParams {
    activePart: Part | null;
    processedGeometry: ProcessedGeometry | null;
    selectedTool: Tool | null;
    punchOrientation: number;
    punchOffset: number;
    snapMode: SnapMode;
    onAddPunches: (punches: Omit<PlacedTool, 'id'>[]) => void;
}

export const useSinglePunchHandler = () => {
    const handleSinglePunch = useCallback((point: Point, params: SinglePunchParams) => {
        const { activePart, processedGeometry, selectedTool, punchOrientation, punchOffset, snapMode, onAddPunches } = params;
        if (!selectedTool || !activePart) return;

        const snapResult = findSnapPoint(point, processedGeometry, snapMode);
        const finalPoint = snapResult?.point ?? point;

        // Режим: Центр фигуры (Отверстия)
        if (snapMode === SnapMode.ShapeCenter) {
            let rotation = punchOrientation;
            if (snapResult?.forceRotation !== undefined) {
                const holeAngle = snapResult.forceRotation;
                const isToolHorizontal = selectedTool.width >= selectedTool.height;
                rotation = isToolHorizontal ? holeAngle : (holeAngle + 90) % 360;
            }
            onAddPunches([{ toolId: selectedTool.id, x: finalPoint.x, y: finalPoint.y, rotation }]);
            return;
        }

        // Режим: Привязка к ребру/вершине
        const placementAngle = snapResult?.angle ?? 0;
        const snapTarget = snapResult?.snapTarget ?? 'middle';
        const wasNormalized = snapResult?.wasNormalized ?? false;

        // Выбираем сторону (внутри/снаружи), которая находится в отходе (Scrap)
        const placementA = calculateEdgePlacement(finalPoint, placementAngle, selectedTool, punchOrientation, punchOffset, snapTarget, wasNormalized, PlacementSide.Outside);
        const placementB = calculateEdgePlacement(finalPoint, placementAngle, selectedTool, punchOrientation, punchOffset, snapTarget, wasNormalized, PlacementSide.Inside);

        let finalPlacement = placementA;
        if (processedGeometry) {
            const isInsideA = isPointInsideContour(placementA, activePart.geometry);
            const isInsideB = isPointInsideContour(placementB, activePart.geometry);

            // Нам нужно положение, где isInside === false (вне материала)
            if (!isInsideA && isInsideB) finalPlacement = placementA;
            else if (isInsideA && !isInsideB) finalPlacement = placementB;
        }

        onAddPunches([{ toolId: selectedTool.id, x: finalPlacement.x, y: finalPlacement.y, rotation: finalPlacement.rotation }]);
    }, []);

    return { handleSinglePunch };
};

/**
 * ОТВЕТСТВЕННОСТЬ: Генерация серии ударов вдоль ближайшего сегмента.
 */
import { useCallback } from 'react';
import { Part, Tool, Point, ToolShape, NibbleSettings, PlacedTool } from '../../types';
import { ProcessedGeometry, findClosestSegment, isPointInsideContour } from '../../services/geometry';
import { generateNibblePunches } from '../../services/punching';

interface NibbleParams {
    activePart: Part | null;
    processedGeometry: ProcessedGeometry | null;
    selectedTool: Tool | null;
    punchOrientation: number;
    nibbleSettings: NibbleSettings;
    onAddPunches: (punches: Omit<PlacedTool, 'id'>[]) => void;
}

export const useNibbleHandler = () => {
    const handleNibble = useCallback((point: Point, params: NibbleParams) => {
        const { activePart, processedGeometry, selectedTool, punchOrientation, nibbleSettings, onAddPunches } = params;
        if (!selectedTool || !activePart) return;

        const closestSeg = findClosestSegment(point, processedGeometry);
        if (!closestSeg) return;

        const segAngle = closestSeg.angle;
        const combinedRotation = segAngle + punchOrientation;

        let perpOffset = (selectedTool.shape === ToolShape.Circle) 
            ? selectedTool.width / 2 
            : (Math.abs(punchOrientation % 180) > 45 && Math.abs(punchOrientation % 180) < 135) 
                ? selectedTool.width / 2 
                : selectedTool.height / 2;

        const ux = Math.cos(segAngle * Math.PI / 180);
        const uy = Math.sin(segAngle * Math.PI / 180);
        const nx = -uy; const ny = ux;
        const mid = { x: (closestSeg.p1.x + closestSeg.p2.x) / 2, y: (closestSeg.p1.y + closestSeg.p2.y) / 2 };

        let finalOffsetSign = 1;
        if (isPointInsideContour({ x: mid.x + nx * perpOffset, y: mid.y + ny * perpOffset }, activePart.geometry)) {
            finalOffsetSign = -1;
        }

        const punches = generateNibblePunches(
            closestSeg.p1, closestSeg.p2, selectedTool, nibbleSettings, 
            closestSeg.angle, closestSeg.wasNormalized, combinedRotation, perpOffset * finalOffsetSign
        );
        onAddPunches(punches);
    }, []);

    return { handleNibble };
};

/**
 * ОТВЕТСТВЕННОСТЬ: Управление двухэтапным вводом для очистки окон.
 */
import { useCallback } from 'react';
import { Tool, Point, DestructSettings, PlacedTool } from '../../types';
import { findSnapPoint, ProcessedGeometry } from '../../services/geometry';
import { generateDestructPunches } from '../../services/punching';

interface DestructParams {
    processedGeometry: ProcessedGeometry | null;
    selectedTool: Tool | null;
    destructSettings: DestructSettings;
    punchCreationStep: number;
    punchCreationPoints: Point[];
    setStep: (s: number) => void;
    setPoints: (p: Point[]) => void;
    onAddPunches: (punches: Omit<PlacedTool, 'id'>[]) => void;
}

export const useDestructHandler = () => {
    const handleDestruct = useCallback((point: Point, params: DestructParams) => {
        const { processedGeometry, selectedTool, destructSettings, punchCreationStep, punchCreationPoints, setStep, setPoints, onAddPunches } = params;
        if (!selectedTool) return;

        const snapResult = findSnapPoint(point, processedGeometry, 'vertex' as any); // Force vertex snap for destruct bounds
        const finalPoint = snapResult?.point ?? point;

        if (punchCreationStep === 0) {
            setPoints([finalPoint]);
            setStep(1);
        } else {
            const [startPoint] = punchCreationPoints;
            const newPunches = generateDestructPunches(startPoint, finalPoint, selectedTool, destructSettings);
            onAddPunches(newPunches);
            setStep(0);
            setPoints([]);
        }
    }, []);

    return { handleDestruct };
};

/**
 * ОТВЕТСТВЕННОСТЬ: Оркестратор ручной пробивки.
 * Сохраняет обратную совместимость API для хука useAppLogic.
 */
import { useCallback } from 'react';
import { Part, Tool, Point, ManualPunchMode, SnapMode, PlacedTool, NibbleSettings, DestructSettings } from '../types';
import { ProcessedGeometry, findSnapPoint } from '../services/geometry';
import { useManualPunchState } from './editor/useManualPunchState';
import { useSinglePunchHandler } from './editor/useSinglePunchHandler';
import { useNibbleHandler } from './editor/useNibbleHandler';
import { useDestructHandler } from './editor/useDestructHandler';

interface UseManualPunchProps {
    activePart: Part | null;
    activePartProcessedGeometry: ProcessedGeometry | null;
    selectedTool: Tool | null;
    manualPunchMode: ManualPunchMode;
    punchOrientation: number;
    punchOffset: number;
    snapMode: SnapMode;
    nibbleSettings: NibbleSettings;
    destructSettings: DestructSettings;
    onAddPunches: (punches: Omit<PlacedTool, 'id'>[]) => void;
    setSelectedPunchId: (id: string | null) => void;
}

export const useManualPunch = ({
    activePart,
    activePartProcessedGeometry,
    selectedTool,
    manualPunchMode,
    punchOrientation,
    punchOffset,
    snapMode,
    nibbleSettings,
    destructSettings,
    onAddPunches,
    setSelectedPunchId
}: UseManualPunchProps) => {

    const state = useManualPunchState();
    const { handleSinglePunch } = useSinglePunchHandler();
    const { handleNibble } = useNibbleHandler();
    const { handleDestruct } = useDestructHandler();

    const handleCanvasClick = useCallback((rawPoint: Point) => {
        // Инверсия Y: View (SVG) -> Model (Cartesian Y-Up)
        const point = { x: rawPoint.x, y: -rawPoint.y };

        setSelectedPunchId(null);
        if (!selectedTool || !activePart) return;

        switch(manualPunchMode) {
            case ManualPunchMode.Punch:
                handleSinglePunch(point, { 
                    activePart, processedGeometry: activePartProcessedGeometry, 
                    selectedTool, punchOrientation, punchOffset, snapMode, onAddPunches 
                });
                break;

            case ManualPunchMode.Nibble:
                handleNibble(point, { 
                    activePart, processedGeometry: activePartProcessedGeometry, 
                    selectedTool, punchOrientation, nibbleSettings, onAddPunches 
                });
                break;

            case ManualPunchMode.Destruct:
                handleDestruct(point, {
                    processedGeometry: activePartProcessedGeometry,
                    selectedTool, destructSettings,
                    punchCreationStep: state.punchCreationStep,
                    punchCreationPoints: state.punchCreationPoints,
                    setStep: state.setPunchCreationStep,
                    setPoints: state.setPunchCreationPoints,
                    onAddPunches
                });
                break;
        }
    }, [
        manualPunchMode, activePart, activePartProcessedGeometry, selectedTool, 
        punchOrientation, punchOffset, snapMode, nibbleSettings, destructSettings,
        state.punchCreationStep, state.punchCreationPoints,
        handleSinglePunch, handleNibble, handleDestruct, onAddPunches, setSelectedPunchId
    ]);

    return { 
        handleCanvasClick, 
        punchCreationStep: state.punchCreationStep, 
        punchCreationPoints: state.punchCreationPoints, 
        resetManualState: state.resetManualState,
        setPunchCreationPoints: state.setPunchCreationPoints,
        setPunchCreationStep: state.setPunchCreationStep
    };
};

