/**
 * ОТВЕТСТВЕННОСТЬ: Безопасное выполнение и логирование ошибок в пользовательских скриптах.
 */
export const handleScriptError = (error: any, scriptName: string): never => {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`[ScriptExecutor] Error in "${scriptName}":`, error);

    // В будущем здесь можно добавить парсинг стека для указания строки ошибки
    throw new Error(`Ошибка в скрипте "${scriptName}": ${message}`);
};

export const scriptLog = (msg: string, ...args: any[]) => {
    if (process.env.NODE_ENV === 'development') {
        console.log(`%c[Script] ${msg}`, 'color: #805ad5; font-weight: bold', ...args);
    }
};

import { Point, DxfEntity, PlacedTool } from '../../types';
import { generateId } from '../../utils/helpers';

export type DrawOp = 
    | { type: 'move', x: number, y: number }
    | { type: 'line', x: number, y: number }
    | { type: 'arc', endX: number, endY: number, centerX: number, centerY: number, clockwise: boolean };

export interface RawPunch {
    toolId: string;
    x: number;
    y: number;
    rotation: number;
    lineId?: string;
}

/**
 * КЛАСС DrawQueue
 * Накапливает результаты выполнения скрипта и производит финальную 
 * нормализацию (центрирование) геометрии.
 */
export class DrawQueue {
    public ops: DrawOp[] = [];
    public rawPunches: RawPunch[] = [];

    addOp(op: DrawOp) { this.ops.push(op); }
    addPunch(p: RawPunch) { this.rawPunches.push(p); }

    /**
     * Вычисляет границы и возвращает данные для сборки Part
     */
    process() {
        if (this.ops.length === 0) throw new Error("Скрипт не сгенерировал геометрию.");

        // 1. Расчет Bounding Box
        let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
        let curX = 0, curY = 0;

        const checkPoint = (x: number, y: number) => {
            minX = Math.min(minX, x); maxX = Math.max(maxX, x);
            minY = Math.min(minY, y); maxY = Math.max(maxY, y);
        };

        this.ops.forEach(op => {
            if (op.type === 'move' || op.type === 'line') {
                checkPoint(op.x, op.y);
                curX = op.x; curY = op.y;
            } else if (op.type === 'arc') {
                checkPoint(op.endX, op.endY);
                // Упрощенный расчет экстремумов дуги (можно расширить до точного)
                const r = Math.sqrt((curX - op.centerX)**2 + (curY - op.centerY)**2);
                checkPoint(op.centerX - r, op.centerY - r);
                checkPoint(op.centerX + r, op.centerY + r);
                curX = op.endX; curY = op.endY;
            }
        });

        const bbox = { minX, minY, maxX, maxY };
        const width = maxX - minX;
        const height = maxY - minY;

        // 2. Нормализация и генерация Path/Entities
        let path = "";
        const entities: DxfEntity[] = [];
        const normX = (v: number) => v - minX;
        const normY = (v: number) => v - minY;

        let penX = 0, penY = 0;

        this.ops.forEach(op => {
            const nx = normX(op.type === 'arc' ? op.endX : op.x);
            const ny = normY(op.type === 'arc' ? op.endY : op.y);

            if (op.type === 'move') {
                path += `M ${nx.toFixed(3)} ${ny.toFixed(3)} `;
            } else if (op.type === 'line') {
                path += `L ${nx.toFixed(3)} ${ny.toFixed(3)} `;
                entities.push({ type: 'LINE', start: { x: penX, y: penY }, end: { x: nx, y: ny } });
            } else if (op.type === 'arc') {
                const r = Math.sqrt((penX - normX(op.centerX))**2 + (penY - normY(op.centerY))**2);
                const largeArc = 0; // Требует доработки для скриптов
                const sweep = op.clockwise ? 1 : 0;
                path += `A ${r.toFixed(3)} ${r.toFixed(3)} 0 ${largeArc} ${sweep} ${nx.toFixed(3)} ${ny.toFixed(3)} `;
                entities.push({ 
                    type: 'ARC', 
                    center: { x: normX(op.centerX), y: normY(op.centerY) }, 
                    radius: r, 
                    startAngle: 0, endAngle: 0 // Заглушка
                });
            }
            penX = nx; penY = ny;
        });

        const punches: PlacedTool[] = this.rawPunches.map(p => ({
            ...p, id: generateId(), x: normX(p.x), y: normY(p.y)
        }));

        return { path: path + " Z", width, height, entities, bbox: { minX: 0, minY: 0, maxX: width, maxY: height }, punches };
    }
}

import { Tool } from '../../types';
import { generateId } from '../../utils/helpers';
import { DrawQueue } from './drawQueue';

const findToolByPattern = (tools: Tool[], pattern: string): Tool | undefined => {
    if (!pattern) return undefined;
    const cleanName = pattern.split(' ')[0].trim().toUpperCase();
    return tools.find(t => t.name.toUpperCase().includes(cleanName));
};

export const createPartBuilder = (queue: DrawQueue, tools: Tool[]) => ({
    SetMaterial: () => {},
    SetControllerIndex: () => {}, 

    StartContour: (x: number, y: number) => {
        queue.addOp({ type: 'move', x, y });
    },
    LineTo: (x: number, y: number) => {
        queue.addOp({ type: 'line', x, y });
    },
    ArcTo: (endX: number, endY: number, centerX: number, centerY: number, clockwise: boolean) => {
        queue.addOp({ type: 'arc', endX, endY, centerX, centerY, clockwise });
    },
    NibbleLine: (toolPattern: string, x1: number, y1: number, x2: number, y2: number, angle: number, pitch: number) => {
        const tool = findToolByPattern(tools, toolPattern);
        if (!tool) return;
        const dist = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
        const count = Math.max(1, Math.ceil(dist / pitch));
        const dx = (x2 - x1) / count;
        const dy = (y2 - y1) / count;
        const lineId = `script_nibble_${generateId()}`;
        for (let i = 0; i <= count; i++) {
            queue.addPunch({ toolId: tool.id, x: x1 + dx * i, y: y1 + dy * i, rotation: angle, lineId });
        }
    },
    Strike: (toolPattern: string, x: number, y: number, angle: number) => {
        const tool = findToolByPattern(tools, toolPattern);
        if (tool) queue.addPunch({ toolId: tool.id, x, y, rotation: angle });
    }
});

import { Tool, Part } from '../types';
import { generateId } from '../utils/helpers';
import { DrawQueue } from './script-executor/drawQueue';
import { createPartBuilder } from './script-executor/partBuilder';
import { handleScriptError } from '../utils/scriptErrorHandler';

/**
 * ВЫПОЛНЕНИЕ ПАРАМЕТРИЧЕСКОГО СКРИПТА
 * 
 * @param basePart - Прототип детали
 * @param scriptCode - Текст JS кода
 * @param tools - Доступные инструменты
 * @param targetWidth - Длина (X)
 * @param targetHeight - Ширина (Y)
 * @param params - Объект дополнительных параметров (a, b, c...)
 */
export const executeParametricScript = (
    basePart: Part, 
    scriptCode: string, 
    tools: Tool[], 
    targetWidth: number, 
    targetHeight: number,
    params: Record<string, any> = {}
): Part => {

    const queue = new DrawQueue();
    const PartBuilder = createPartBuilder(queue, tools);

    // Выполнение
    try {
        const generateFunc = new Function('Part', 'Length', 'Width', 'width', 'height', 'tools', 'Params', scriptCode);
        generateFunc(PartBuilder, targetWidth, targetHeight, targetWidth, targetHeight, tools, params);
    } catch (err) {
        handleScriptError(err, basePart.name);
    }

    // Обработка накопленной очереди
    const processed = queue.process();

    return {
        ...basePart,
        id: generateId(),
        name: `${basePart.name}_${targetWidth}x${targetHeight}`,
        faceWidth: targetWidth,
        faceHeight: targetHeight,
        geometry: {
            path: processed.path,
            width: processed.width,
            height: processed.height,
            entities: processed.entities,
            bbox: processed.bbox
        },
        punches: processed.punches,
        script: scriptCode
    };
};

import { NestResultSheet } from '../../types';

export interface NestingProgressUpdate {
    sheets: NestResultSheet[];
    progress: number;
    status: string;
}

export interface PackerItem {
    uid: string;
    partId: string;
    name: string;
    width: number;
    height: number;
    offsetX: number;
    offsetY: number;
    allowedRotations: number[];
    hasCommonLine: boolean;
    area: number;
    preferredRotation?: number;
    aspectRatio: number;
}

export interface PlacedResult {
    x: number;      // Координата X (относительно области упаковки)
    y: number;      // Координата Y
    rotation: number;
    ox: number;     // Смещение начала координат детали (origin offset)
    oy: number;
    width: number;  // Итоговая ширина в этой ротации
    height: number; // Итоговая высота
}

/**
 * Единый интерфейс для всех алгоритмов раскроя
 */
export interface INestingPacker {
    readonly sheetW: number;
    readonly sheetH: number;
    findPosition(item: PackerItem): Promise<PlacedResult | null>;
    placeItem(item: PackerItem, result: PlacedResult): void;
    getPlacedItems(): { item: PackerItem; result: PlacedResult }[];
}

import { NestingSettings, SheetStock, SheetUtilizationStrategy } from '../../types';

/**
 * Вспомогательная функция выбора заготовки листа на основе стратегии
 */
export function selectStockSheet(settings: NestingSettings): SheetStock | null {
    const sheets = settings.availableSheets.filter(s => s.useInNesting && s.quantity > 0);
    if (sheets.length === 0) return null;

    switch (settings.utilizationStrategy) {
        case SheetUtilizationStrategy.SmallestFirst:
            return [...sheets].sort((a, b) => (a.width * a.height) - (b.width * b.height))[0];
        case SheetUtilizationStrategy.BestFit:
            // В данной реализации просто берем первый доступный
            return sheets[0];
        case SheetUtilizationStrategy.ListedOrder:
        default:
            return sheets[0];
    }
}

import { ScheduledPart, Part, Tool } from '../../types';
import { PackerItem } from './types';
import { generateId } from '../../utils/helpers';
import { getRotatedExtents } from '../geometry';

/**
 * Превращает заказ деталей в плоский список элементов для упаковщика с расчетом габаритов.
 */
export const preparePackerItems = (
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[]
): PackerItem[] => {
    const items: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        const ext0 = getRotatedExtents(part, 0, tools);
        const allowed: number[] = [0];
        if (sp.nesting.allow0_180) allowed.push(180);
        if (sp.nesting.allow90_270) { allowed.push(90); allowed.push(270); }

        for (let i = 0; i < sp.quantity; i++) {
            items.push({
                uid: generateId(),
                partId: sp.partId,
                name: part.name,
                width: ext0.width,
                height: ext0.height,
                offsetX: ext0.ox,
                offsetY: ext0.oy,
                allowedRotations: allowed,
                hasCommonLine: sp.nesting.commonLine,
                area: ext0.width * ext0.height,
                aspectRatio: ext0.width / ext0.height
            });
        }
    }

    // Сортировка по убыванию площади (стандарт для упаковки)
    return items.sort((a, b) => b.area - a.area);
};

import { INestingPacker, PackerItem, PlacedResult } from '../types';
import { Part, Tool } from '../../../types';
import { getRotatedExtents } from '../../geometry';

interface FreeRect { x: number; y: number; w: number; h: number; }

export class RectanglePacker implements INestingPacker {
    private freeRects: FreeRect[];
    private placed: { item: PackerItem; result: PlacedResult }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly useCommonLine: boolean,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {
        this.freeRects = [{ x: 0, y: 0, w: sheetW, h: sheetH }];
    }

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        let bestScore = Infinity;
        let bestRect: FreeRect | null = null;
        let bestRot = 0;
        let finalSX = 0;
        let finalSY = 0;

        const rotations = [0];
        if (item.allowedRotations.includes(90) || item.allowedRotations.includes(270)) rotations.push(90);

        for (const rect of this.freeRects) {
            for (const rot of rotations) {
                const isRot = rot === 90;
                const curW = isRot ? item.height : item.width;
                const curH = isRot ? item.width : item.height;

                const sX = rect.x === 0 ? 0 : this.spacingX;
                const sY = rect.y === 0 ? 0 : this.spacingY;

                const effW = curW + sX;
                const effH = curH + sY;

                if (effW <= rect.w && effH <= rect.h) {
                    const score = Math.min(rect.w - effW, rect.h - effH);
                    if (score < bestScore) {
                        bestScore = score;
                        bestRect = rect;
                        bestRot = rot;
                        finalSX = sX;
                        finalSY = sY;
                    }
                }
            }
        }

        if (bestRect) {
            const partDef = this.parts.find(p => p.id === item.partId);
            const ext = partDef ? getRotatedExtents(partDef, bestRot, this.tools) : { ox: 0, oy: 0, width: 0, height: 0 };
            return {
                x: bestRect.x + finalSX,
                y: bestRect.y + finalSY,
                rotation: bestRot,
                ox: ext.ox,
                oy: ext.oy,
                width: ext.width,
                height: ext.height
            };
        }
        return null;
    }

    placeItem(item: PackerItem, result: PlacedResult) {
        this.placed.push({ item, result });
        const used: FreeRect = { x: result.x, y: result.y, w: result.width, h: result.height };

        const nextFree: FreeRect[] = [];
        for (const f of this.freeRects) {
            if (this.intersects(f, used)) {
                if (used.x > f.x) nextFree.push({ x: f.x, y: f.y, w: used.x - f.x, h: f.h });
                if (used.x + used.w < f.x + f.w) nextFree.push({ x: used.x + used.w, y: f.y, w: (f.x + f.w) - (used.x + used.w), h: f.h });
                if (used.y > f.y) nextFree.push({ x: f.x, y: f.y, w: f.w, h: used.y - f.y });
                if (used.y + used.h < f.y + f.h) nextFree.push({ x: f.x, y: used.y + used.h, w: f.w, h: (f.y + f.h) - (used.y + used.h) });
            } else {
                nextFree.push(f);
            }
        }
        this.freeRects = nextFree.filter(r => r.w > 1 && r.h > 1);
    }

    private intersects(a: FreeRect, b: FreeRect) {
        return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
    }

    getPlacedItems() { return this.placed; }
}

import { INestingPacker, PackerItem, PlacedResult } from '../types';
import { Part, Tool, Point } from '../../../types';
import { getRotatedExtents, doPartsIntersect } from '../../geometry';

export class ComplexPacker implements INestingPacker {
    private placed: { item: PackerItem; result: PlacedResult }[] = [];

    constructor(
        public readonly sheetW: number,
        public readonly sheetH: number,
        private readonly spacingX: number,
        private readonly spacingY: number,
        private readonly parts: Part[],
        private readonly tools: Tool[]
    ) {}

    async findPosition(item: PackerItem): Promise<PlacedResult | null> {
        const partDef = this.parts.find(p => p.id === item.partId);
        if (!partDef) return null;

        const step = 5; // Шаг поиска (точность)
        const rotationCandidates = [...item.allowedRotations];
        if (item.preferredRotation !== undefined && !rotationCandidates.includes(item.preferredRotation)) {
            rotationCandidates.unshift(item.preferredRotation);
        }

        for (let x = 0; x <= this.sheetW - step; x += step) {
            if (x % 50 === 0) await new Promise(resolve => setTimeout(resolve, 0));

            for (const rot of rotationCandidates) {
                const extents = getRotatedExtents(partDef, rot, this.tools);
                if (x + extents.width > this.sheetW) continue;

                for (let y = 0; y <= this.sheetH - extents.height; y += step) {
                    const candidateOrigin: Point = { x: x + extents.ox, y: y + extents.oy };

                    let collision = false;
                    for (const placed of this.placed) {
                        const pPartDef = this.parts.find(p => p.id === placed.item.partId);
                        if (!pPartDef) continue;

                        const pOrigin: Point = { 
                            x: placed.result.x + placed.result.ox, 
                            y: placed.result.y + placed.result.oy 
                        };

                        if (doPartsIntersect(
                            partDef, candidateOrigin, rot,
                            pPartDef, pOrigin, placed.result.rotation,
                            Math.max(this.spacingX, this.spacingY)
                        )) {
                            collision = true;
                            break;
                        }
                    }

                    if (!collision) {
                        return { x, y, rotation: rot, ox: extents.ox, oy: extents.oy, width: extents.width, height: extents.height };
                    }
                }
            }
        }
        return null;
    }

    placeItem(item: PackerItem, result: PlacedResult) {
        this.placed.push({ item, result });
    }

    getPlacedItems() { return this.placed; }
}

import { 
    NestResultSheet, 
    ScheduledPart, 
    Part, 
    Tool, 
    NestingSettings
} from './types';
import { generateId } from './utils/helpers';
import { INestingPacker, NestingProgressUpdate } from './nesting/types';
import { selectStockSheet } from './nesting/utils';
import { preparePackerItems } from './nesting/scoring';
import { RectanglePacker } from './nesting/algo/RectanglePacker';
import { ComplexPacker } from './nesting/algo/ComplexPacker';

export type { NestingProgressUpdate };

/**
 * ГЕНЕРАТОР РАСКРОЯ
 * Главная точка входа, координирующая процесс укладки деталей на листы.
 */
export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestingProgressUpdate> {

    // 1. Подготовка очереди деталей с расчетом площадей и приоритетов
    const itemsToPack = preparePackerItems(scheduledParts, allParts, tools);

    const totalToPack = itemsToPack.length;
    let totalPackedCount = 0;
    const completedSheets: NestResultSheet[] = [];
    let remainingItems = [...itemsToPack];

    // 2. Цикл по листам (пока есть неразмещенные детали)
    while (remainingItems.length > 0) {
        const stockSheet = selectStockSheet(settings);
        if (!stockSheet) break;

        const effectiveW = stockSheet.width - settings.sheetMarginLeft - settings.sheetMarginRight;
        const effectiveH = stockSheet.height - settings.sheetMarginTop - settings.sheetMarginBottom;

        // Инициализация упаковщика согласно настройкам (прямоугольники или сложная форма)
        const packer: INestingPacker = settings.nestAsRectangle 
            ? new RectanglePacker(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, settings.useCommonLine, allParts, tools)
            : new ComplexPacker(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, allParts, tools);

        let packedOnThisSheet: string[] = [];

        for (const item of remainingItems) {
            const pos = await packer.findPosition(item);
            if (pos) {
                packer.placeItem(item, pos);
                packedOnThisSheet.push(item.uid);
                totalPackedCount++;

                // Промежуточное обновление прогресса
                yield { 
                    sheets: [...completedSheets], 
                    progress: (totalPackedCount / totalToPack) * 100, 
                    status: `Размещение: ${item.name}` 
                };
            }
        }

        if (packedOnThisSheet.length === 0) {
            console.error("Item too big for sheet", remainingItems[0]);
            remainingItems.shift(); // Пропускаем деталь, которая не лезет ни на один пустой лист
            continue;
        }

        // Удаляем успешно упакованные из общего списка
        remainingItems = remainingItems.filter(it => !packedOnThisSheet.includes(it.uid));

        // 3. Формирование итогового объекта листа
        const placedItems = packer.getPlacedItems();
        const usedAreaPx = placedItems.reduce((sum, p) => sum + p.item.area, 0);
        const totalAreaPx = stockSheet.width * stockSheet.height;

        const resultSheet: NestResultSheet = {
            id: generateId(),
            sheetName: `Sheet ${completedSheets.length + 1}`,
            stockSheetId: stockSheet.id,
            width: stockSheet.width,
            height: stockSheet.height,
            material: stockSheet.material,
            thickness: stockSheet.thickness,
            usedArea: (usedAreaPx / totalAreaPx) * 100,
            scrapPercentage: 100 - (usedAreaPx / totalAreaPx) * 100,
            partCount: placedItems.length,
            quantity: 1,
            placedParts: placedItems.map(p => ({
                id: generateId(),
                partId: p.item.partId,
                x: p.result.x + settings.sheetMarginLeft + p.result.ox,
                y: p.result.y + settings.sheetMarginBottom + p.result.oy,
                rotation: p.result.rotation
            }))
        };

        completedSheets.push(resultSheet);
        yield { sheets: [...completedSheets], progress: (totalPackedCount / totalToPack) * 100, status: `Лист #${completedSheets.length} готов` };
    }
}

import { 
    NestResultSheet, 
    ScheduledPart, 
    Part, 
    Tool, 
    NestingSettings
} from '../types';
import { generateId } from '../utils/helpers';
import { INestingPacker, NestingProgressUpdate } from './nesting/types';
import { selectStockSheet } from './nesting/utils';
import { preparePackerItems } from './nesting/scoring';
import { RectanglePacker } from './nesting/algo/RectanglePacker';
import { ComplexPacker } from './nesting/algo/ComplexPacker';

export type { NestingProgressUpdate };

/**
 * ГЕНЕРАТОР РАСКРОЯ
 * Главная точка входа, координирующая процесс укладки деталей на листы.
 */
export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestingProgressUpdate> {

    // 1. Подготовка очереди деталей с расчетом площадей и приоритетов
    const itemsToPack = preparePackerItems(scheduledParts, allParts, tools);

    const totalToPack = itemsToPack.length;
    let totalPackedCount = 0;
    const completedSheets: NestResultSheet[] = [];
    let remainingItems = [...itemsToPack];

    // 2. Цикл по листам (пока есть неразмещенные детали)
    while (remainingItems.length > 0) {
        const stockSheet = selectStockSheet(settings);
        if (!stockSheet) break;

        const effectiveW = stockSheet.width - settings.sheetMarginLeft - settings.sheetMarginRight;
        const effectiveH = stockSheet.height - settings.sheetMarginTop - settings.sheetMarginBottom;

        // Инициализация упаковщика согласно настройкам (прямоугольники или сложная форма)
        const packer: INestingPacker = settings.nestAsRectangle 
            ? new RectanglePacker(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, settings.useCommonLine, allParts, tools)
            : new ComplexPacker(effectiveW, effectiveH, settings.partSpacingX, settings.partSpacingY, allParts, tools);

        let packedOnThisSheet: string[] = [];

        for (const item of remainingItems) {
            const pos = await packer.findPosition(item);
            if (pos) {
                packer.placeItem(item, pos);
                packedOnThisSheet.push(item.uid);
                totalPackedCount++;

                // Промежуточное обновление прогресса
                yield { 
                    sheets: [...completedSheets], 
                    progress: (totalPackedCount / totalToPack) * 100, 
                    status: `Размещение: ${item.name}` 
                };
            }
        }

        if (packedOnThisSheet.length === 0) {
            console.error("Item too big for sheet", remainingItems[0]);
            remainingItems.shift(); // Пропускаем деталь, которая не лезет ни на один пустой лист
            continue;
        }

        // Удаляем успешно упакованные из общего списка
        remainingItems = remainingItems.filter(it => !packedOnThisSheet.includes(it.uid));

        // 3. Формирование итогового объекта листа
        const placedItems = packer.getPlacedItems();
        const usedAreaPx = placedItems.reduce((sum, p) => sum + p.item.area, 0);
        const totalAreaPx = stockSheet.width * stockSheet.height;

        const resultSheet: NestResultSheet = {
            id: generateId(),
            sheetName: `Sheet ${completedSheets.length + 1}`,
            stockSheetId: stockSheet.id,
            width: stockSheet.width,
            height: stockSheet.height,
            material: stockSheet.material,
            thickness: stockSheet.thickness,
            usedArea: (usedAreaPx / totalAreaPx) * 100,
            scrapPercentage: 100 - (usedAreaPx / totalAreaPx) * 100,
            partCount: placedItems.length,
            quantity: 1,
            placedParts: placedItems.map(p => ({
                id: generateId(),
                partId: p.item.partId,
                x: p.result.x + settings.sheetMarginLeft + p.result.ox,
                y: p.result.y + settings.sheetMarginBottom + p.result.oy,
                rotation: p.result.rotation
            }))
        };

        completedSheets.push(resultSheet);
        yield { sheets: [...completedSheets], progress: (totalPackedCount / totalToPack) * 100, status: `Лист #${completedSheets.length} готов` };
    }
}

import { Tool, Part } from '../types';
import { generateId } from '../utils/helpers';
import { DrawQueue } from './script-executor/drawQueue';
import { createPartBuilder } from './script-executor/partBuilder';
import { handleScriptError } from '../utils/scriptErrorHandler';

/**
 * ВЫПОЛНЕНИЕ ПАРАМЕТРИЧЕСКОГО СКРИПТА
 * 
 * @param basePart - Прототип детали
 * @param scriptCode - Текст JS кода
 * @param tools - Доступные инструменты
 * @param targetWidth - Длина (X)
 * @param targetHeight - Ширина (Y)
 * @param params - Объект дополнительных параметров (a, b, c...)
 */
export const executeParametricScript = (
    basePart: Part, 
    scriptCode: string, 
    tools: Tool[], 
    targetWidth: number, 
    targetHeight: number,
    params: Record<string, any> = {}
): Part => {

    const queue = new DrawQueue();
    const PartBuilder = createPartBuilder(queue, tools);

    // Выполнение в "песочнице"
    try {
        // Мы затеняем глобальные объекты (window, document, и т.д.), передавая их как аргументы,
        // но при вызове передаем undefined. Это предотвращает доступ к DOM и сети из скрипта.
        const generateFunc = new Function(
            'window', 'document', 'fetch', 'XMLHttpRequest', 'localStorage', 'sessionStorage', 'alert', 'console', // Shadowed globals
            'Part', 'Length', 'Width', 'width', 'height', 'tools', 'Params', // Actual API
            `"use strict";\n${scriptCode}`
        );

        generateFunc(
            undefined, undefined, undefined, undefined, undefined, undefined, undefined, console, // Block globals, allow console
            PartBuilder, targetWidth, targetHeight, targetWidth, targetHeight, tools, params
        );
    } catch (err) {
        handleScriptError(err, basePart.name);
    }

    // Обработка накопленной очереди
    const processed = queue.process();

    return {
        ...basePart,
        id: generateId(),
        name: `${basePart.name}_${targetWidth}x${targetHeight}`,
        faceWidth: targetWidth,
        faceHeight: targetHeight,
        geometry: {
            path: processed.path,
            width: processed.width,
            height: processed.height,
            entities: processed.entities,
            bbox: processed.bbox
        },
        punches: processed.punches,
        script: scriptCode
    };
};

import { DxfEntity, Point } from '../types';

/**
 * Parses a simplified DXF file content.
 * Handles LWPOLYLINE, CIRCLE, ARC and LINE entities.
 * Robust against whitespace and case sensitivity.
 */
export const parseDxf = (dxfContent: string): DxfEntity[] => {
  // Safety limit to prevent browser freeze
  const MAX_ENTITIES = 10000;

  const lines = dxfContent.split(/\r?\n/);
  const entities: DxfEntity[] = [];
  let currentEntity: DxfEntity | null = null;
  let lastLwPolylineX: number | null = null; // State for LWPOLYLINE vertices

  const pushCurrentEntity = () => {
    if (currentEntity) {
      entities.push(currentEntity);
      currentEntity = null;
    }
    lastLwPolylineX = null; // Reset state for new entity
  };

  // Correctly iterate by pairs of code and value
  for (let i = 0; i < lines.length - 1; i += 2) {
    // Safety Break
    if (entities.length >= MAX_ENTITIES) {
        console.warn(`DXF Parse: Reached maximum entity limit (${MAX_ENTITIES}). Parsing stopped early.`);
        break;
    }

    const codeStr = lines[i].trim();
    if (codeStr === '') {
        // Skip blank lines, but adjust index to not get out of sync
        i -=1; 
        continue;
    };

    const value = lines[i + 1].trim().toUpperCase(); // Normalize value to uppercase

    const code = parseInt(codeStr, 10);
    if (isNaN(code)) continue;

    if (code === 0) {
      pushCurrentEntity(); // A group code 0 indicates the start of a new entity.

      switch(value) {
        case 'LWPOLYLINE':
          currentEntity = { type: 'LWPOLYLINE', vertices: [], closed: false };
          break;
        case 'CIRCLE':
          currentEntity = { type: 'CIRCLE', center: { x: 0, y: 0 }, radius: 0 };
          break;
        case 'ARC':
           currentEntity = { type: 'ARC', center: { x: 0, y: 0 }, radius: 0, startAngle: 0, endAngle: 0 };
           break;
        case 'LINE':
          currentEntity = { type: 'LINE', start: { x: 0, y: 0 }, end: { x: 0, y: 0 } };
          break;
        case 'ENDSEC':
            currentEntity = null;
            break;
        default:
          currentEntity = null; // Ignore other entity types
          break;
      }
    }

    if (currentEntity) {
        // Parse values based on entity type
        // Note: parseFloat handles the uppercase string fine if it's numeric
        const floatVal = parseFloat(value);

        switch (currentEntity.type) {
            case 'LWPOLYLINE':
                 if (code === 10) { // X coordinate
                    lastLwPolylineX = floatVal;
                 } else if (code === 20 && lastLwPolylineX !== null) { // Y coordinate
                    currentEntity.vertices.push({ x: lastLwPolylineX, y: floatVal });
                    lastLwPolylineX = null;
                 } else if (code === 70) {
                    // Bit code 1 = closed
                    currentEntity.closed = (parseInt(value, 10) & 1) === 1;
                 }
                break;
            case 'CIRCLE':
            case 'ARC':
                 switch(code) {
                    case 10: currentEntity.center.x = floatVal; break;
                    case 20: currentEntity.center.y = floatVal; break;
                    case 40: currentEntity.radius = floatVal; break;
                    case 50: if(currentEntity.type === 'ARC') currentEntity.startAngle = floatVal; break;
                    case 51: if(currentEntity.type === 'ARC') currentEntity.endAngle = floatVal; break;
                 }
                 break;
            case 'LINE':
                switch(code) {
                    case 10: currentEntity.start.x = floatVal; break;
                    case 20: currentEntity.start.y = floatVal; break;
                    case 11: currentEntity.end.x = floatVal; break;
                    case 21: currentEntity.end.y = floatVal; break;
                }
                break;
        }
    }
  }

  pushCurrentEntity(); // Push the very last entity

  return entities;
};

const degreesToRadians = (degrees: number) => degrees * (Math.PI / 180);

/**
 * Converts an array of parsed DXF entities into a single SVG path string.
 * Coordinates are normalized to (0,0) at Bottom-Left (Y-Up Cartesian).
 * RETURNS: Normalized Entities as well, for consistent storage in Part.
 */
export const dxfEntitiesToSvg = (entities: DxfEntity[]): { 
    path: string, 
    width: number, 
    height: number, 
    bbox: { minX: number, minY: number, maxX: number, maxY: number },
    normalizedEntities: DxfEntity[] 
} => {
    if (entities.length === 0) {
        return { path: '', width: 0, height: 0, bbox: { minX: 0, minY: 0, maxX: 0, maxY: 0 }, normalizedEntities: [] };
    }

    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

    // 1. Calculate Bounding Box of RAW entities
    const updateBounds = (x: number, y: number) => {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
    }

    entities.forEach(entity => {
        switch(entity.type) {
            case 'LWPOLYLINE':
                entity.vertices.forEach(v => updateBounds(v.x, v.y));
                break;
            case 'LINE':
                updateBounds(entity.start.x, entity.start.y);
                updateBounds(entity.end.x, entity.end.y);
                break;
            case 'CIRCLE':
                updateBounds(entity.center.x - entity.radius, entity.center.y - entity.radius);
                updateBounds(entity.center.x + entity.radius, entity.center.y + entity.radius);
                break;
            case 'ARC':
                // Simplified bbox for Arc (using center + radius points)
                const startRad = degreesToRadians(entity.startAngle);
                const endRad = degreesToRadians(entity.endAngle);
                updateBounds(entity.center.x + entity.radius * Math.cos(startRad), entity.center.y + entity.radius * Math.sin(startRad));
                updateBounds(entity.center.x + entity.radius * Math.cos(endRad), entity.center.y + entity.radius * Math.sin(endRad));

                // Check cardinal points
                for (let deg = 0; deg <= 360; deg += 90) {
                     // Check if deg is within start-end range
                     // Normalize angles to 0-360 for comparison
                     let s = entity.startAngle;
                     let e = entity.endAngle;
                     if(e < s) e += 360;
                     let d = deg;
                     if(d < s) d += 360;

                     if (d >= s && d <= e) {
                         const rRad = degreesToRadians(deg);
                         updateBounds(entity.center.x + entity.radius * Math.cos(rRad), entity.center.y + entity.radius * Math.sin(rRad));
                     }
                }
                break;
        }
    });

    // 2. Exact bounds
    const width = maxX - minX;
    const height = maxY - minY;

    // 3. Create Normalized Entities (Deep Copy with shift)
    const normalizedEntities: DxfEntity[] = JSON.parse(JSON.stringify(entities));

    const normalizePoint = (p: Point) => {
        p.x -= minX;
        p.y -= minY;
    };

    normalizedEntities.forEach(entity => {
        switch(entity.type) {
            case 'LWPOLYLINE':
                entity.vertices.forEach(normalizePoint);
                break;
            case 'LINE':
                normalizePoint(entity.start);
                normalizePoint(entity.end);
                break;
            case 'CIRCLE':
            case 'ARC':
                normalizePoint(entity.center);
                break;
        }
    });

    // 4. Generate SVG Path from NORMALIZED entities
    const pathDataParts: string[] = [];

    normalizedEntities.forEach(entity => {
        switch(entity.type) {
            case 'LWPOLYLINE':
                const pathData = entity.vertices
                    .map((v, i) => `${i === 0 ? 'M' : 'L'} ${v.x.toFixed(3)} ${v.y.toFixed(3)}`)
                    .join(' ');
                pathDataParts.push(pathData + (entity.closed ? ' Z' : ''));
                break;
            case 'LINE':
                pathDataParts.push(`M ${entity.start.x.toFixed(3)} ${entity.start.y.toFixed(3)} L ${entity.end.x.toFixed(3)} ${entity.end.y.toFixed(3)}`);
                break;
            case 'CIRCLE':
                const c = entity.center;
                const r = entity.radius;
                // Draw two arcs to form a circle
                pathDataParts.push(`M ${(c.x - r).toFixed(3)} ${c.y.toFixed(3)} A ${r.toFixed(3)} ${r.toFixed(3)} 0 1 0 ${(c.x + r).toFixed(3)} ${c.y.toFixed(3)}`);
                pathDataParts.push(`M ${(c.x + r).toFixed(3)} ${c.y.toFixed(3)} A ${r.toFixed(3)} ${r.toFixed(3)} 0 1 0 ${(c.x - r).toFixed(3)} ${c.y.toFixed(3)}`);
                break;
            case 'ARC':
                const arcCenter = entity.center;
                const arcRadius = entity.radius;
                const startAngle = entity.startAngle;
                const endAngle = entity.endAngle;

                const startRad = degreesToRadians(startAngle);
                const endRad = degreesToRadians(endAngle);

                const startPoint = {
                    x: arcCenter.x + arcRadius * Math.cos(startRad),
                    y: arcCenter.y + arcRadius * Math.sin(startRad)
                };
                const endPoint = {
                    x: arcCenter.x + arcRadius * Math.cos(endRad),
                    y: arcCenter.y + arcRadius * Math.sin(endRad)
                };

                let angleSpan = endAngle - startAngle;
                if (angleSpan < 0) angleSpan += 360;

                const largeArcFlag = angleSpan > 180 ? 1 : 0;
                const sweepFlag = 1; // Standard Cartesian Counter-Clockwise

                pathDataParts.push(`M ${startPoint.x.toFixed(3)} ${startPoint.y.toFixed(3)} A ${arcRadius.toFixed(3)} ${arcRadius.toFixed(3)} 0 ${largeArcFlag} ${sweepFlag} ${endPoint.x.toFixed(3)} ${endPoint.y.toFixed(3)}`);
                break;
        }
    });

    const finalPath = pathDataParts.join(' ');

    // Return Normalized BBox (0,0, W, H)
    const normalizedBbox = { minX: 0, minY: 0, maxX: width, maxY: height };

    return { 
        path: finalPath, 
        width, 
        height, 
        bbox: normalizedBbox,
        normalizedEntities 
    };
};
